Files["blockos/apps/clock/main.lua"] = [[
-- Clock: big clock, alarms (real or Minecraft time), stopwatch and timer.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Config = BlockOS.Require("config")
local Schedule = BlockOS.Require("schedule")

local Page = Ui.Page.new()
local Tab = 1
local Build

local Font = Gfx.Font

local Stopwatch = { Running = false, Start = 0, Elapsed = 0, Laps = {} }
local Timer = { Running = false, Duration = 300000, Remaining = 300000, EndsAt = 0, Fired = false }

local function Now()
	return os.epoch("utc")
end

local function BigWidth(Text)
	local Width = 0
	for Index = 1, #Text do
		local Glyph = Font[Text:sub(Index, Index)]
		Width = Width + (Glyph and #Glyph[1] or 1) + 1
	end
	return Width - 1
end

local function DrawBig(T, X, Y, Text, Color, Bg)
	for Index = 1, #Text do
		local Glyph = Font[Text:sub(Index, Index)]
		if (Glyph) then
			for Row = 1, 5 do
				local Line = Glyph[Row]
				for Column = 1, #Line do
					local Filled = Line:sub(Column, Column) == "#"
					Gfx.Write(T, X + Column - 1, Y + Row - 1, " ", Color, Filled and Color or Bg)
				end
			end
			X = X + #Glyph[1] + 1
		else
			X = X + 2
		end
	end
end

local function CenterBig(T, Y, Text, Color, Bg, W)
	DrawBig(T, math.floor((W - BigWidth(Text)) / 2) + 1, Y, Text, Color, Bg)
end

local function FormatDuration(Milliseconds, Centis)
	local Total = math.max(0, math.floor(Milliseconds / 1000))
	local Hours = math.floor(Total / 3600)
	local Minutes = math.floor(Total / 60) % 60
	local Seconds = Total % 60
	local Text
	if (Hours > 0) then
		Text = string.format("%d:%02d:%02d", Hours, Minutes, Seconds)
	else
		Text = string.format("%02d:%02d", Minutes, Seconds)
	end
	if (Centis) then
		Text = Text .. string.format(".%02d", math.floor(Milliseconds / 10) % 100)
	end
	return Text
end

local function StopwatchTime()
	if (Stopwatch.Running) then
		return Stopwatch.Elapsed + (Now() - Stopwatch.Start)
	end
	return Stopwatch.Elapsed
end

local function TimerRemaining()
	if (Timer.Running) then
		return math.max(0, Timer.EndsAt - Now())
	end
	return Timer.Remaining
end

local function BuildClock(W, H)
	Page:Add(Ui.Canvas.new({
		X = 1, Y = 2, W = W, H = H - 1,
		OnDraw = function(Self, T, Th)
			local Settings = Config.Settings()
			local Text = os.date(Settings.Clock24 and "%H:%M" or "%I:%M")
			CenterBig(T, Self.Y + 1, Text, Th.Accent, Th.WindowBg, W)
			Gfx.Center(T, Self.Y + 7, os.date("%A, %d %B %Y") .. "  " .. os.date(":%S") .. (Settings.Clock24 and "" or os.date(" %p")), Th.Text, Th.WindowBg)
			local Game = textutils.formatTime(os.time(), Settings.Clock24)
			Gfx.Center(T, Self.Y + 9, "Minecraft: Day " .. os.day() .. ", " .. Game, Th.SubText, Th.WindowBg)
			local Hours = os.time()
			local Phase = (Hours >= 6 and Hours < 18) and "\15 Daytime" or "\7 Night"
			Gfx.Center(T, Self.Y + 10, Phase, (Hours >= 6 and Hours < 18) and colors.orange or colors.lightBlue, Th.WindowBg)
		end
	}))
end

local function FormatAlarm(Alarm)
	if (Alarm.Source == "game") then
		return textutils.formatTime(Alarm.Time, true) .. " MC"
	end
	return string.format("%02d:%02d", math.floor(Alarm.Time / 60), Alarm.Time % 60)
end

local function BuildAlarms(W, H)
	local Data = Schedule.Load()
	local List = Page:Add(Ui.List.new({ X = 1, Y = 2, W = W, H = H - 3 }))
	local Items = {}
	for _, Alarm in ipairs(Data.Alarms) do
		table.insert(Items, {
			Text = FormatAlarm(Alarm) .. "  " .. (Alarm.Label or "Alarm"),
			Icon = Alarm.Enabled and "\7" or "o",
			IconFg = Alarm.Enabled and "Accent" or "SubText",
			Right = Alarm.Enabled and "on" or "off",
			Alarm = Alarm
		})
	end
	List:SetItems(Items)
	List.OnActivate = function(_, _, Item)
		Item.Alarm.Enabled = not Item.Alarm.Enabled
		Schedule.Save()
		Build()
	end
	List.OnContext = function(_, _, Item, X, Y)
		if (not Item) then return end
		local Choice = Ui.ContextMenu(X, Y, { Item.Alarm.Enabled and "Turn Off" or "Turn On", "Delete" })
		if (Choice == 1) then
			Item.Alarm.Enabled = not Item.Alarm.Enabled
			Schedule.Save()
		elseif (Choice == 2) then
			Schedule.RemoveAlarm(Item.Alarm.ID)
		end
		Build()
	end
	if (#Items == 0) then
		Page:Add(Ui.Label.new({ X = 2, Y = 3, W = W - 2, Text = "No alarms. Alarms ring while BlockOS is running.", Fg = "SubText", H = 2 }))
	end
	Page:Add(Ui.Button.new({ X = 2, Y = H, Text = " + Add Alarm ", Style = "primary", OnClick = function()
		local Index = Ui.Choose("Alarm clock", { "Real time", "Minecraft time" })
		if (not Index) then return end
		local Text = Ui.Prompt("New Alarm", "Time (HH:MM, 24-hour):", Index == 1 and os.date("%H:%M") or "06:00")
		if (not Text) then return end
		local Hour, Minute = Text:match("^(%d%d?):(%d%d)$")
		if (not Hour or tonumber(Hour) > 23 or tonumber(Minute) > 59) then
			Ui.Alert("New Alarm", "Enter the time as HH:MM.")
			return
		end
		local Label = Ui.Prompt("New Alarm", "Label:", "Alarm") or "Alarm"
		if (Index == 1) then
			Schedule.AddAlarm({ Label = Label, Time = tonumber(Hour) * 60 + tonumber(Minute), Source = "real" })
		else
			Schedule.AddAlarm({ Label = Label, Time = tonumber(Hour) + tonumber(Minute) / 60, Source = "game" })
		end
		Build()
	end }))
	Page:Add(Ui.Label.new({ X = 18, Y = H, W = W - 18, Text = "Double-click toggles", Fg = "SubText" }))
end

local function BuildStopwatch(W, H)
	Page:Add(Ui.Canvas.new({
		X = 1, Y = 2, W = W, H = 6,
		OnDraw = function(Self, T, Th)
			local Text = FormatDuration(StopwatchTime(), false)
			CenterBig(T, Self.Y + 1, Text, Stopwatch.Running and Th.Accent or Th.Text, Th.WindowBg, W)
			Gfx.Center(T, Self.Y + 6, string.format(".%02d", math.floor(StopwatchTime() / 10) % 100), Th.SubText, Th.WindowBg)
		end
	}))
	local Laps = {}
	for Index = #Stopwatch.Laps, 1, -1 do
		table.insert(Laps, { Text = "Lap " .. Index, Right = FormatDuration(Stopwatch.Laps[Index], true) })
	end
	Page:Add(Ui.List.new({ X = 2, Y = 9, W = W - 2, H = math.max(1, H - 10), Items = Laps }))
	Page:Add(Ui.Button.new({ X = 2, Y = H, W = 9, Text = function() return Stopwatch.Running and "Stop" or "Start" end, Style = "primary", OnClick = function()
		if (Stopwatch.Running) then
			Stopwatch.Elapsed = StopwatchTime()
			Stopwatch.Running = false
		else
			Stopwatch.Start = Now()
			Stopwatch.Running = true
		end
	end }))
	Page:Add(Ui.Button.new({ X = 12, Y = H, W = 7, Text = "Lap", OnClick = function()
		if (Stopwatch.Running) then
			table.insert(Stopwatch.Laps, StopwatchTime())
			Build()
		end
	end }))
	Page:Add(Ui.Button.new({ X = 20, Y = H, W = 8, Text = "Reset", OnClick = function()
		Stopwatch = { Running = false, Start = 0, Elapsed = 0, Laps = {} }
		Build()
	end }))
end

local function BuildTimer(W, H)
	Page:Add(Ui.Canvas.new({
		X = 1, Y = 2, W = W, H = 6,
		OnDraw = function(Self, T, Th)
			local Remaining = TimerRemaining()
			CenterBig(T, Self.Y + 1, FormatDuration(Remaining + 999, false), Timer.Running and Th.Accent or Th.Text, Th.WindowBg, W)
		end
	}))
	Page:Add(Ui.Progress.new({ X = 3, Y = 8, W = W - 4, Value = function()
		return Timer.Duration > 0 and (1 - TimerRemaining() / Timer.Duration) or 0
	end }))
	local function Adjust(Delta)
		if (Timer.Running) then return end
		Timer.Remaining = math.max(0, Timer.Remaining + Delta)
		Timer.Duration = Timer.Remaining
	end
	local Presets = { { "-1m", -60000 }, { "+1m", 60000 }, { "+5m", 300000 }, { "+10s", 10000 } }
	local X = 2
	for _, Preset in ipairs(Presets) do
		Page:Add(Ui.Button.new({ X = X, Y = 10, W = 6, Text = Preset[1], OnClick = function() Adjust(Preset[2]) end }))
		X = X + 7
	end
	Page:Add(Ui.Button.new({ X = 2, Y = H, W = 9, Text = function() return Timer.Running and "Pause" or "Start" end, Style = "primary", OnClick = function()
		if (Timer.Running) then
			Timer.Remaining = TimerRemaining()
			Timer.Running = false
		elseif (Timer.Remaining > 0) then
			Timer.EndsAt = Now() + Timer.Remaining
			Timer.Running = true
			Timer.Fired = false
		end
	end }))
	Page:Add(Ui.Button.new({ X = 12, Y = H, W = 8, Text = "Reset", OnClick = function()
		Timer.Running = false
		Timer.Remaining = Timer.Duration
	end }))
end

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	Page:Add(Ui.Tabs.new({
		X = 1, Y = 1, W = W, Items = { "Clock", "Alarms", "Stopwatch", "Timer" }, Selected = Tab,
		OnChange = function(_, Index)
			Tab = Index
			Build()
		end
	}))
	local Builders = { BuildClock, BuildAlarms, BuildStopwatch, BuildTimer }
	Builders[Tab](W, H)
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name)
	if (Name == "blockos_schedule" and Tab == 2) then
		Build()
		return true
	end
	return false
end

Page:SetInterval(.1, function()
	if (Timer.Running and TimerRemaining() <= 0 and not Timer.Fired) then
		Timer.Fired = true
		Timer.Running = false
		Timer.Remaining = 0
		BlockOS.Notify("Timer", "Time's up!", { AppID = "clock", Repeat = 3, Duration = 10 })
	end
	if (Tab == 1) then
		return os.clock() % 1 < .1
	end
	return (Tab == 3 and Stopwatch.Running) or (Tab == 4)
end)

Page:Run()
]]
Files["blockos/apps/devices/app.cfg"] = [[
{ Name = "Devices", Description = "Inspect and control attached peripherals and redstone.", Width = 46, Height = 15, Single = true, Icon = { Lines = { "[\7]", "|||" }, Fg = "cyan", Bg = "black" } }
]]
Files["blockos/apps/devices/main.lua"] = [[
-- Devices: inspect this computer, redstone sides and every attached peripheral, with per-type actions.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")

local Page = Ui.Page.new()
local SelectedID = "computer"
local Build

local TypeIcons = {
	monitor = { "\8", colors.lightBlue }, modem = { "\29", colors.orange }, speaker = { "\14", colors.red },
	drive = { "\22", colors.gray }, printer = { "\127", colors.yellow }, computer = { "\8", colors.cyan },
	turtle = { "\4", colors.lime }, redstone = { "\7", colors.red }
}

local function Entries()
	local List = {
		{ ID = "computer", Text = "This Computer", Icon = "\8", IconFg = colors.cyan },
		{ ID = "redstone", Text = "Redstone", Icon = "\7", IconFg = colors.red }
	}
	local Names = peripheral.getNames()
	table.sort(Names)
	for _, Name in ipairs(Names) do
		local Kind = peripheral.getType(Name)
		local Icon = TypeIcons[Kind] or { "\4", colors.gray }
		table.insert(List, { ID = Name, Text = Name, Icon = Icon[1], IconFg = Icon[2], Kind = Kind })
	end
	return List
end

local function Info(X, Y, W, Lines)
	for Index, Line in ipairs(Lines) do
		Page:Add(Ui.Label.new({ X = X, Y = Y + Index - 1, W = 10, Text = Line[1], Fg = "SubText" }))
		Page:Add(Ui.Label.new({ X = X + 10, Y = Y + Index - 1, W = W - 10, Text = tostring(Line[2]) }))
	end
	return Y + #Lines + 1
end

local function Buttons(X, Y, W, List)
	local BX = X
	for _, Entry in ipairs(List) do
		local Width = #Entry[1] + 2
		if (BX + Width > X + W) then
			BX = X
			Y = Y + 2
		end
		Page:Add(Ui.Button.new({ X = BX, Y = Y, W = Width, Text = Entry[1], Style = Entry[3], OnClick = function()
			local Ok, Err = pcall(Entry[2])
			if (not Ok) then Ui.Alert("Devices", tostring(Err)) end
			Build()
		end }))
		BX = BX + Width + 1
	end
	return Y + 2
end

local Details = {}

function Details.computer(X, Y, W)
	local Uptime = math.floor(os.clock())
	Info(X, Y, W, {
		{ "Label", os.getComputerLabel() or "(none)" },
		{ "ID", os.getComputerID() },
		{ "Kind", (turtle and "Turtle" or (pocket and "Pocket computer" or "Computer")) .. (term.isColor() and ", advanced" or "") },
		{ "Version", _HOST or os.version() },
		{ "Uptime", string.format("%dh %02dm %02ds", math.floor(Uptime / 3600), math.floor(Uptime / 60) % 60, Uptime % 60) },
		{ "World", "Day " .. os.day() .. ", " .. textutils.formatTime(os.time(), true) },
		{ "Storage", Gfx.FormatSize(fs.getFreeSpace("/")) .. " free" },
		{ "Devices", #peripheral.getNames() .. " attached" }
	})
end

function Details.redstone(X, Y, W)
	Page:Add(Ui.Label.new({ X = X, Y = Y, W = W, Text = "Side      In  Out", Fg = "SubText" }))
	for Index, Side in ipairs(redstone.getSides()) do
		local Row = Y + Index
		Page:Add(Ui.Label.new({ X = X, Y = Row, W = 9, Text = Side }))
		local Input = redstone.getAnalogInput(Side)
		Page:Add(Ui.Label.new({ X = X + 10, Y = Row, W = 3, Text = tostring(Input), Fg = (Input > 0) and colors.red or "SubText" }))
		Page:Add(Ui.Toggle.new({ X = X + 14, Y = Row, Value = redstone.getOutput(Side), OnChange = function(_, Value)
			redstone.setOutput(Side, Value)
		end }))
	end
end

local function MonitorDetails(Name, X, Y, W)
	local Monitor = peripheral.wrap(Name)
	local MW, MH = Monitor.getSize()
	Y = Info(X, Y, W, { { "Size", MW .. " x " .. MH }, { "Colour", Monitor.isColor() and "yes" or "no" }, { "Scale", Monitor.getTextScale and Monitor.getTextScale() or "?" } })
	Buttons(X, Y, W, {
		{ "Test Pattern", function()
			local Palette = { colors.red, colors.orange, colors.yellow, colors.lime, colors.cyan, colors.blue, colors.purple, colors.magenta }
			for Row = 1, MH do
				Monitor.setCursorPos(1, Row)
				Monitor.setBackgroundColor(Palette[(Row - 1) % #Palette + 1])
				Monitor.clearLine()
			end
			Monitor.setCursorPos(2, 2)
			Monitor.setTextColor(colors.white)
			Monitor.write("BlockOS")
		end },
		{ "Clear", function()
			Monitor.setBackgroundColor(colors.black)
			Monitor.clear()
		end },
		{ "Scale -", function() Monitor.setTextScale(math.max(.5, Monitor.getTextScale() - .5)) end },
		{ "Scale +", function() Monitor.setTextScale(math.min(5, Monitor.getTextScale() + .5)) end }
	})
end

local function ModemDetails(Name, X, Y, W)
	local Modem = peripheral.wrap(Name)
	local Lines = { { "Type", Modem.isWireless() and "Wireless" or "Wired" }, { "Rednet", rednet.isOpen(Name) and "open" or "closed" } }
	if (not Modem.isWireless() and Modem.getNamesRemote) then
		table.insert(Lines, { "Network", #Modem.getNamesRemote() .. " remote peripherals" })
	end
	Y = Info(X, Y, W, Lines)
	Buttons(X, Y, W, {
		{ rednet.isOpen(Name) and "Close Rednet" or "Open Rednet", function()
			if (rednet.isOpen(Name)) then rednet.close(Name) else rednet.open(Name) end
		end }
	})
end

local function SpeakerDetails(Name, X, Y, W)
	local Speaker = peripheral.wrap(Name)
	Y = Info(X, Y, W, { { "Type", "Speaker" } })
	Buttons(X, Y, W, {
		{ "Chime", function()
			for Index, Pitch in ipairs({ 12, 16, 19, 24 }) do
				Speaker.playNote("chime", 1, Pitch)
				if (Index < 4) then sleep(.15) end
			end
		end },
		{ "Bell", function() Speaker.playNote("bell", 1, 12) end },
		{ "Sound...", function()
			local Sound = Ui.Prompt("Play Sound", "Sound ID:", "entity.experience_orb.pickup")
			if (Sound) then Speaker.playSound(Sound) end
		end },
		{ "Stop", function() Speaker.stop() end }
	})
end

local function DriveDetails(Name, X, Y, W)
	local Lines = { { "Disk", disk.isPresent(Name) and "inserted" or "empty" } }
	if (disk.hasData(Name)) then
		table.insert(Lines, { "Label", disk.getLabel(Name) or "(none)" })
		table.insert(Lines, { "Mount", "/" .. disk.getMountPath(Name) })
		table.insert(Lines, { "Disk ID", tostring(disk.getID(Name)) })
	elseif (disk.hasAudio(Name)) then
		table.insert(Lines, { "Music", disk.getAudioTitle(Name) })
	end
	Y = Info(X, Y, W, Lines)
	local Actions = {}
	if (disk.hasData(Name)) then
		table.insert(Actions, { "Open in Finder", function() BlockOS.Launch("finder", { "/" .. disk.getMountPath(Name) }) end })
	end
	if (disk.hasAudio(Name)) then
		table.insert(Actions, { "Play", function() disk.playAudio(Name) end })
		table.insert(Actions, { "Stop", function() disk.stopAudio(Name) end })
	end
	if (disk.isPresent(Name)) then
		table.insert(Actions, { "Eject", function() disk.eject(Name) end })
	end
	Buttons(X, Y, W, Actions)
end

local function PrinterDetails(Name, X, Y, W)
	local Printer = peripheral.wrap(Name)
	Y = Info(X, Y, W, { { "Ink", Printer.getInkLevel() }, { "Paper", Printer.getPaperLevel() } })
	local function PrintLines(Title, Lines)
		if (not Printer.newPage()) then error("Add ink and paper first.", 0) end
		Printer.setPageTitle(Title)
		local PW, PH = Printer.getPageSize()
		local Row = 1
		for _, Line in ipairs(Lines) do
			for _, Piece in ipairs(Gfx.Wrap(Line, PW)) do
				if (Row > PH) then
					Printer.endPage()
					if (not Printer.newPage()) then return end
					Printer.setPageTitle(Title)
					Row = 1
				end
				Printer.setCursorPos(1, Row)
				Printer.write(Piece)
				Row = Row + 1
			end
		end
		Printer.endPage()
	end
	Buttons(X, Y, W, {
		{ "Test Page", function()
			PrintLines("BlockOS Test", { "BlockOS printer test", "", "Computer #" .. os.getComputerID(), os.date("%Y-%m-%d %H:%M"), "", "If you can read this, printing works." })
		end },
		{ "Print File...", function()
			local Path = Ui.PickFile({ Dir = "/home/Documents" })
			if (not Path) then return end
			local Lines = {}
			local Handle = fs.open(Path, "r")
			for Line in (Handle.readAll() .. "\n"):gmatch("(.-)\n") do
				table.insert(Lines, Line)
			end
			Handle.close()
			PrintLines(fs.getName(Path), Lines)
		end }
	})
end

local function ComputerDetails(Name, X, Y, W)
	local Remote = peripheral.wrap(Name)
	Y = Info(X, Y, W, { { "ID", Remote.getID() }, { "Label", Remote.getLabel() or "(none)" }, { "Running", Remote.isOn() and "yes" or "no" } })
	Buttons(X, Y, W, {
		{ "Turn On", function() Remote.turnOn() end },
		{ "Reboot", function() Remote.reboot() end },
		{ "Shut Down", function() Remote.shutdown() end, "danger" }
	})
end

local function GenericDetails(Name, X, Y, W, H)
	Page:Add(Ui.Label.new({ X = X, Y = Y, W = W, Text = "Methods", Fg = "SubText" }))
	local Items = {}
	local Methods = peripheral.getMethods(Name) or {}
	table.sort(Methods)
	for _, Method in ipairs(Methods) do
		table.insert(Items, { Text = Method .. "()" })
	end
	Page:Add(Ui.List.new({ X = X, Y = Y + 1, W = W, H = math.max(1, H - 2), Items = Items }))
end

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	local SideW = (W >= 40) and 16 or 0
	local List = Page:Add(Ui.List.new({ X = 1, Y = 1, W = SideW, H = H, Bg = "Panel", SingleClick = true, Visible = SideW > 0 }))
	local Items = Entries()
	List:SetItems(Items)
	local Current
	for Index, Item in ipairs(Items) do
		if (Item.ID == SelectedID) then
			List.Selected = Index
			Current = Item
		end
	end
	if (not Current) then
		SelectedID = "computer"
		Current = Items[1]
		List.Selected = 1
	end
	List.OnActivate = function(_, _, Item)
		SelectedID = Item.ID
		Build()
	end
	local X = SideW + 2
	local ContentW = W - SideW - 2
	local Title = Current.Kind and (Current.Text .. " (" .. Current.Kind .. ")") or Current.Text
	if (SideW == 0) then
		Page:Add(Ui.Button.new({ X = 1, Y = 1, W = W, Text = "\31 " .. Title, Bg = "Panel", OnClick = function()
			local Names = {}
			for _, Item in ipairs(Items) do table.insert(Names, Item.Text) end
			local Index = Ui.Choose("Devices", Names)
			if (Index) then
				SelectedID = Items[Index].ID
				Build()
			end
		end }))
	else
		Page:Add(Ui.Label.new({ X = X, Y = 1, W = ContentW, Text = Title, Fg = "Accent" }))
	end
	local Y = 3
	if (Current.ID == "computer" or Current.ID == "redstone") then
		Details[Current.ID](X, Y, ContentW, H - 2)
	elseif (Current.Kind == "monitor") then
		MonitorDetails(Current.ID, X, Y, ContentW)
	elseif (Current.Kind == "modem") then
		ModemDetails(Current.ID, X, Y, ContentW)
	elseif (Current.Kind == "speaker") then
		SpeakerDetails(Current.ID, X, Y, ContentW)
	elseif (Current.Kind == "drive") then
		DriveDetails(Current.ID, X, Y, ContentW)
	elseif (Current.Kind == "printer") then
		PrinterDetails(Current.ID, X, Y, ContentW)
	elseif (Current.Kind == "computer" or Current.Kind == "turtle") then
		ComputerDetails(Current.ID, X, Y, ContentW)
	else
		GenericDetails(Current.ID, X, Y, ContentW, H - 2)
	end
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name)
	if (Name == "peripheral" or Name == "peripheral_detach" or Name == "disk" or Name == "disk_eject" or Name == "monitor_resize") then
		Build()
		return true
	elseif (Name == "redstone" and SelectedID == "redstone") then
		Build()
		return true
	end
	return false
end

Page:SetInterval(1, function()
	if (SelectedID ~= "computer") then return false end
	Build()
	return true
end)

Page:Run()
]]
