{ Name = "DiskCopy", Description = "Copy, back up, erase and clone floppy disks.", Width = 42, Height = 14, Single = true, Icon = { Lines = { "[=]", "[=]" }, Fg = "black", Bg = "lightGray" } }
]]
Files["blockos/apps/diskcopy/main.lua"] = [[
-- DiskCopy: duplicate, back up, restore, erase and label floppy disks, or make an installer disk.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Config = BlockOS.Require("config")

local Page = Ui.Page.new()
local Drives = {}
local Progress = 0
local Status = "Insert a disk into a disk drive."
local Busy = false
local DriveList
local Build

local function ScanDrives()
	Drives = {}
	for _, Name in ipairs(peripheral.getNames()) do
		if (peripheral.getType(Name) == "drive") then
			local Entry = { Name = Name, Present = disk.isPresent(Name), HasData = disk.hasData(Name) }
			if (Entry.HasData) then
				Entry.Mount = "/" .. disk.getMountPath(Name)
				Entry.Label = disk.getLabel(Name)
				Entry.Free = fs.getFreeSpace(Entry.Mount)
				Entry.Capacity = fs.getCapacity and fs.getCapacity(Entry.Mount) or nil
			elseif (Entry.Present and disk.hasAudio(Name)) then
				Entry.Audio = disk.getAudioTitle(Name)
			end
			table.insert(Drives, Entry)
		end
	end
end

local function ListFiles(Root, Relative, Into, Exclude)
	Into = Into or {}
	local Dir = fs.combine(Root, Relative or "")
	for _, Name in ipairs(fs.list(Dir)) do
		local Child = fs.combine(Relative or "", Name)
		if (not (Exclude and Exclude[Child])) then
			if (fs.isDir(fs.combine(Root, Child))) then
				table.insert(Into, { Path = Child, Dir = true })
				ListFiles(Root, Child, Into, Exclude)
			else
				table.insert(Into, { Path = Child, Size = fs.getSize(fs.combine(Root, Child)) })
			end
		end
	end
	return Into
end

local function TreeSize(Files)
	local Total = 0
	for _, File in ipairs(Files) do
		Total = Total + (File.Size or 0)
	end
	return Total
end

local function SetProgress(Value, Text)
	Progress = Value
	Status = Text
	Page:Draw()
end

local function CopyTree(Source, Target, Exclude)
	local Files = ListFiles(Source, nil, nil, Exclude)
	local Size = TreeSize(Files)
	if (Size > fs.getFreeSpace(Target)) then
		return false, "Not enough space: needs " .. Gfx.FormatSize(Size) .. ", " .. Gfx.FormatSize(fs.getFreeSpace(Target)) .. " free."
	end
	local Done = 0
	for Index, File in ipairs(Files) do
		local Destination = fs.combine(Target, File.Path)
		if (File.Dir) then
			if (not fs.exists(Destination)) then fs.makeDir(Destination) end
		else
			if (fs.exists(Destination)) then fs.delete(Destination) end
			fs.copy(fs.combine(Source, File.Path), Destination)
			Done = Done + File.Size
		end
		SetProgress(Index / #Files, "Copying " .. File.Path)
		if (Index % 8 == 0) then sleep(0) end
	end
	return true, #Files .. " items, " .. Gfx.FormatSize(Done)
end

local function EraseMount(Mount)
	for _, Name in ipairs(fs.list(Mount)) do
		fs.delete(fs.combine(Mount, Name))
	end
end

local function SelectedDrive()
	local Item = DriveList and DriveList.Items[DriveList.Selected]
	return Item and Item.Drive
end

local function RequireDisk()
	local Drive = SelectedDrive()
	if (not Drive or not Drive.HasData) then
		Ui.Alert("DiskCopy", "Select a drive with a floppy disk in it.")
		return nil
	end
	return Drive
end

local function Run(Task)
	if (Busy) then return end
	Busy = true
	local Ok, Result, Detail = pcall(Task)
	Busy = false
	if (not Ok) then
		Status = "Error: " .. tostring(Result)
	elseif (Result == false) then
		Status = tostring(Detail)
	elseif (Result) then
		Status = tostring(Result)
		Progress = 1
	end
	ScanDrives()
	Build()
end

local Actions = {
	{ Text = "Duplicate", Task = function()
		local Source = RequireDisk()
		if (not Source) then return end
		local Targets, Names = {}, {}
		for _, Drive in ipairs(Drives) do
			if (Drive ~= Source and Drive.HasData) then
				table.insert(Targets, Drive)
				table.insert(Names, (Drive.Label or "Untitled") .. " (" .. Drive.Name .. ")")
			end
		end
		if (#Targets == 0) then
			Ui.Alert("Duplicate", "Insert a second disk into another drive.")
			return
		end
		local Index = Ui.Choose("Copy to", Names)
		if (not Index) then return end
		local Target = Targets[Index]
		if (not Ui.Confirm("Duplicate", "Erase \"" .. (Target.Label or "Untitled") .. "\" and copy \"" .. (Source.Label or "Untitled") .. "\" onto it?", "Duplicate")) then return end
		EraseMount(Target.Mount)
		local Ok, Text = CopyTree(Source.Mount, Target.Mount)
		if (Ok and Source.Label) then disk.setLabel(Target.Name, Source.Label) end
		return Ok and ("Duplicated: " .. Text) or false, Text
	end },
	{ Text = "Back Up", Task = function()
		local Source = RequireDisk()
		if (not Source) then return end
		local Name = (Source.Label or "disk"):gsub("[^%w%-_ ]", "") .. " " .. os.date("%Y-%m-%d %H%M")
		local Target = fs.combine("/home/Backups", Name)
		fs.makeDir(Target)
		local Ok, Text = CopyTree(Source.Mount, Target)
		return Ok and ("Backed up to /" .. Target) or false, Text
	end },
	{ Text = "Restore", Task = function()
		local Target = RequireDisk()
		if (not Target) then return end
		local Folder = Ui.PickFile({ Title = "Restore from folder", Dir = "/home/Backups", Folders = true })
		if (not Folder) then return end
		if (not Ui.Confirm("Restore", "Erase the disk and copy " .. Folder .. " onto it?", "Restore")) then return end
		EraseMount(Target.Mount)
		local Ok, Text = CopyTree(Folder, Target.Mount)
		return Ok and ("Restored: " .. Text) or false, Text
	end },
	{ Text = "Erase", Task = function()
		local Target = RequireDisk()
		if (not Target) then return end
		if (not Ui.Confirm("Erase Disk", "Permanently erase everything on \"" .. (Target.Label or "Untitled") .. "\"?", "Erase")) then return end
		EraseMount(Target.Mount)
		return "Disk erased"
	end },
	{ Text = "Label", Task = function()
		local Drive = SelectedDrive()
		if (not Drive or not Drive.Present) then return end
		local Label = Ui.Prompt("Label Disk", "New label:", Drive.Label or "")
		if (Label == nil) then return end
		disk.setLabel(Drive.Name, #Label > 0 and Label or nil)
		return "Label updated"
	end },
	{ Text = "Installer", Task = function()
		local Target = RequireDisk()
		if (not Target) then return end
		if (not Ui.Confirm("Installer Disk", "Write a BlockOS network installer to this disk? Any computer that boots it can install BlockOS.", "Write")) then return end
		local Repo = Config.Settings().UpdateURL or Config.Repo
		local Script = table.concat({
			"-- BlockOS installer disk",
			"term.clear() term.setCursorPos(1, 1)",
			"print(\"BlockOS installer disk\")",
			"write(\"Install BlockOS on this computer? (y/n) \")",
			"if (read():lower():sub(1, 1) ~= \"y\") then return end",
			"shell.run(\"wget\", \"run\", " .. string.format("%q", Repo .. "install.lua") .. ")"
		}, "\n")
		Config.WriteText(fs.combine(Target.Mount, "startup.lua"), Script .. "\n")
		disk.setLabel(Target.Name, "BlockOS Installer")
		return "Installer disk ready"
	end },
	{ Text = "Eject", Task = function()
		local Drive = SelectedDrive()
		if (Drive) then disk.eject(Drive.Name) end
	end }
}

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	local Items = {}
	for _, Drive in ipairs(Drives) do
		local Text, Right
		if (Drive.HasData) then
			Text = (Drive.Label or "Untitled") .. "  " .. Drive.Mount
			Right = Drive.Capacity and (Gfx.FormatSize(Drive.Capacity - Drive.Free) .. " used") or (Gfx.FormatSize(Drive.Free) .. " free")
		elseif (Drive.Audio) then
			Text, Right = "\14 " .. Drive.Audio, "music"
		else
			Text, Right = "(empty)", ""
		end
		table.insert(Items, { Text = Drive.Name .. ": " .. Text, Icon = "\22", IconFg = Drive.HasData and "Accent" or "SubText", Right = Right, Drive = Drive })
	end
	local Selected = DriveList and DriveList.Selected or 1
	DriveList = Page:Add(Ui.List.new({ X = 1, Y = 1, W = W, H = math.max(3, H - 8), Bg = "Panel" }))
	DriveList:SetItems(Items)
	DriveList.Selected = math.min(math.max(Selected, 1), #Items)
	if (#Items == 0) then
		Page:Add(Ui.Label.new({ X = 2, Y = 2, W = W - 2, H = 2, Bg = "Panel", Fg = "SubText", Text = "No disk drives attached. Place a disk drive next to the computer." }))
	end
	local X, Y = 2, H - 6
	for _, Action in ipairs(Actions) do
		local Width = #Action.Text + 2
		if (X + Width > W + 1) then
			X = 2
			Y = Y + 2
		end
		Page:Add(Ui.Button.new({ X = X, Y = Y, W = Width, Text = Action.Text, Enabled = not Busy, OnClick = function() Run(Action.Task) end }))
		X = X + Width + 1
	end
	Page:Add(Ui.Progress.new({ X = 2, Y = H - 1, W = W - 2, Value = function() return Progress end }))
	Page:Add(Ui.Label.new({ X = 1, Y = H, W = W, Fg = "SubText", Text = function() return " " .. Status end }))
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name)
	if (not Busy and (Name == "disk" or Name == "disk_eject" or Name == "peripheral" or Name == "peripheral_detach")) then
		ScanDrives()
		Progress = 0
		Build()
		return true
	end
	return false
end

ScanDrives()
Page:Run()
]]
Files["blockos/apps/editor/app.cfg"] = [[
{ Name = "Editor", Description = "Code editor with Lua syntax highlighting.", Width = 46, Height = 15, Icon = { Lines = { "</>", "\140\140 " }, Fg = "white", Bg = "purple" } }
]]
Files["blockos/apps/editor/main.lua"] = [=[
-- Editor: a code editor with Lua syntax highlighting, selection, undo, find and run.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Config = BlockOS.Require("config")

local Args = { ... }

local Keywords = {}
for Word in ("and break do else elseif end false for function goto if in local nil not or repeat return then true until while"):gmatch("%S+") do
	Keywords[Word] = true
end

local Builtins = {}
for Word in ([[print write read pairs ipairs require type tostring tonumber error assert pcall xpcall select next
	setmetatable getmetatable rawget rawset rawequal load loadstring loadfile dofile unpack sleep table string math
	os io fs term colors colours peripheral rednet http textutils shell multishell window keys turtle coroutine
	parallel settings disk redstone rs vector gps paintutils bit32 bit _G _ENV self BlockOS commands pocket]]):gmatch("%S+") do
	Builtins[Word] = true
end

local Hex = Gfx.Hex

local Doc = {
	Lines = { "" },
	X = 1,
	Y = 1,
	ScrollX = 0,
	ScrollY = 0,
	Path = nil,
	Modified = false,
	Anchor = nil,
	UseTabs = false,
	Undo = {},
	Redo = {}
}

local States = {}
local ValidStates = 0
local Message, MessageTime = nil, 0
local Modifiers = Ui.Modifiers
local Find = ""
local Page = Ui.Page.new()
local Editor

local function Palette(Th)
	if (Th.Dark) then
		return {
			Bg = colors.black, Text = colors.white, Keyword = colors.yellow, String = colors.red,
			Comment = colors.green, Number = colors.purple, Builtin = colors.cyan, Operator = colors.lightGray,
			Gutter = colors.gray, GutterFg = colors.lightGray, Selection = colors.blue
		}
	end
	return {
		Bg = colors.white, Text = colors.black, Keyword = colors.blue, String = colors.red,
		Comment = colors.green, Number = colors.purple, Builtin = colors.cyan, Operator = colors.gray,
		Gutter = colors.lightGray, GutterFg = colors.gray, Selection = colors.lightBlue
	}
end

local function SetMessage(Text)
	Message = Text
	MessageTime = os.clock()
end

local function IsLua()
	return not Doc.Path or Doc.Path:match("%.lua$") ~= nil or not Doc.Path:match("%.%w+$")
end

--
-- Highlighting
--

local function Highlight(Line, State, P)
	local Colors = {}
	local Length = #Line
	local Index = 1
	local function Paint(From, To, Color)
		local Code = Hex[Color]
		for Position = From, math.min(To, Length) do
			Colors[Position] = Code
		end
	end
	if (not IsLua()) then
		Paint(1, Length, P.Text)
		return table.concat(Colors), nil
	end
	if (State) then
		local _, Finish = Line:find(State.Close, 1, true)
		local Color = (State.Kind == "comment") and P.Comment or P.String
		if (not Finish) then
			Paint(1, Length, Color)
			return table.concat(Colors), State
		end
		Paint(1, Finish, Color)
		Index = Finish + 1
		State = nil
	end
	while (Index <= Length) do
		local Char = Line:sub(Index, Index)
		if (Line:sub(Index, Index + 1) == "--") then
			local Level = Line:match("^%[(=*)%[", Index + 2)
			if (Level) then
				local Close = "]" .. Level .. "]"
				local _, Finish = Line:find(Close, Index + 4 + #Level, true)
				if (not Finish) then
					Paint(Index, Length, P.Comment)
					return table.concat(Colors), { Kind = "comment", Close = Close }
				end
				Paint(Index, Finish, P.Comment)
				Index = Finish + 1
			else
				Paint(Index, Length, P.Comment)
				Index = Length + 1
			end
		elseif (Char == "\"" or Char == "'") then
			local Position = Index + 1
			while (Position <= Length) do
				local Next = Line:sub(Position, Position)
				if (Next == "\\") then
					Position = Position + 2
				elseif (Next == Char) then
					break
				else
					Position = Position + 1
				end
			end
			Paint(Index, Position, P.String)
			Index = Position + 1
		elseif (Char == "[" and Line:match("^%[=*%[", Index)) then
			local Level = Line:match("^%[(=*)%[", Index)
			local Close = "]" .. Level .. "]"
			local _, Finish = Line:find(Close, Index + 2 + #Level, true)
			if (not Finish) then
				Paint(Index, Length, P.String)
				return table.concat(Colors), { Kind = "string", Close = Close }
			end
			Paint(Index, Finish, P.String)
			Index = Finish + 1
		elseif (Char:match("%d") or (Char == "." and Line:sub(Index + 1, Index + 1):match("%d"))) then
			local _, Finish = Line:find("^0[xX]%x+", Index)
			if (not Finish) then _, Finish = Line:find("^%d*%.?%d*[eE][%+%-]?%d+", Index) end
			if (not Finish) then _, Finish = Line:find("^%d*%.?%d*", Index) end
			Paint(Index, Finish, P.Number)
			Index = Finish + 1
		elseif (Char:match("[%a_]")) then
			local Start, Finish = Line:find("^[%w_]+", Index)
			local Word = Line:sub(Start, Finish)
			local Color = P.Text
			if (Keywords[Word]) then
				Color = P.Keyword
			elseif (Builtins[Word]) then
				Color = P.Builtin
			end
			Paint(Start, Finish, Color)
			Index = Finish + 1
		else
			Paint(Index, Index, Char:match("[%+%-%*/%%%^#=<>~%.]") and P.Operator or P.Text)
			Index = Index + 1
		end
	end
	return table.concat(Colors), nil
end

local function Invalidate(FromLine)
	ValidStates = math.min(ValidStates, FromLine - 1)
end

local function StateAt(Line, P)
	if (ValidStates < 1) then
		States[1] = nil
		ValidStates = 1
	end
	while (ValidStates < Line) do
		local _, Next = Highlight(Doc.Lines[ValidStates] or "", States[ValidStates], P)
		ValidStates = ValidStates + 1
		States[ValidStates] = Next
	end
	return States[Line]
end

--
-- Text model
--

local function TabWidth()
	return 2
end

local function DisplayWidth(Line, Upto)
	local Width = 0
	for Index = 1, math.min(Upto, #Line) do
		Width = Width + ((Line:sub(Index, Index) == "\t") and TabWidth() or 1)
	end
	return Width
end

local function CharFromDisplay(Line, Column)
	local Width = 0
	for Index = 1, #Line do
		local Step = (Line:sub(Index, Index) == "\t") and TabWidth() or 1
		if (Width + Step > Column) then return Index end
		Width = Width + Step
	end
	return #Line + 1
end

local function Snapshot()
	return { Text = table.concat(Doc.Lines, "\n"), X = Doc.X, Y = Doc.Y }
end

local function Restore(Shot)
	Doc.Lines = {}
	for Line in (Shot.Text .. "\n"):gmatch("(.-)\n") do
		table.insert(Doc.Lines, Line)
	end
	if (#Doc.Lines == 0) then Doc.Lines = { "" } end
	Doc.X, Doc.Y = Shot.X, Shot.Y
	Doc.Anchor = nil
	Invalidate(1)
end

local LastUndoKind, LastUndoTime = nil, 0

local function PushUndo(Kind)
	local Now = os.clock()
	if (Kind == "type" and LastUndoKind == "type" and Now - LastUndoTime < 1.5) then
		LastUndoTime = Now
		return
	end
	table.insert(Doc.Undo, Snapshot())
	if (#Doc.Undo > 100) then table.remove(Doc.Undo, 1) end
	Doc.Redo = {}
	LastUndoKind, LastUndoTime = Kind, Now
end

local function Clamp()
	Doc.Y = math.max(1, math.min(Doc.Y, #Doc.Lines))
	Doc.X = math.max(1, math.min(Doc.X, #Doc.Lines[Doc.Y] + 1))
end

local function SelectionRange()
	if (not Doc.Anchor) then return nil end
	local AX, AY, BX, BY = Doc.Anchor.X, Doc.Anchor.Y, Doc.X, Doc.Y
	if (AY > BY or (AY == BY and AX > BX)) then
		AX, AY, BX, BY = BX, BY, AX, AY
	end
	if (AX == BX and AY == BY) then return nil end
	return AX, AY, BX, BY
end

local function SelectedText()
	local AX, AY, BX, BY = SelectionRange()
	if (not AX) then return nil end
	if (AY == BY) then
		return Doc.Lines[AY]:sub(AX, BX - 1)
	end
	local Parts = { Doc.Lines[AY]:sub(AX) }
	for Line = AY + 1, BY - 1 do
		table.insert(Parts, Doc.Lines[Line])
	end
	table.insert(Parts, Doc.Lines[BY]:sub(1, BX - 1))
	return table.concat(Parts, "\n")
end

local function DeleteSelection()
	local AX, AY, BX, BY = SelectionRange()
	Doc.Anchor = nil
	if (not AX) then return false end
	local Head = Doc.Lines[AY]:sub(1, AX - 1)
	local Tail = Doc.Lines[BY]:sub(BX)
	for _ = AY + 1, BY do
		table.remove(Doc.Lines, AY + 1)
	end
	Doc.Lines[AY] = Head .. Tail
	Doc.X, Doc.Y = AX, AY
	Doc.Modified = true
	Invalidate(AY)
	return true
end

local function InsertText(Text)
	DeleteSelection()
	Text = Text:gsub("\r\n", "\n"):gsub("\r", "\n")
	local Line = Doc.Lines[Doc.Y]
	local Head, Tail = Line:sub(1, Doc.X - 1), Line:sub(Doc.X)
	local Pieces = {}
	for Piece in (Text .. "\n"):gmatch("(.-)\n") do
		table.insert(Pieces, Piece)
	end
	if (#Pieces == 1) then
		Doc.Lines[Doc.Y] = Head .. Pieces[1] .. Tail
		Doc.X = Doc.X + #Pieces[1]
	else
		Doc.Lines[Doc.Y] = Head .. Pieces[1]
		for Index = 2, #Pieces do
			table.insert(Doc.Lines, Doc.Y + Index - 1, Pieces[Index])
		end
		local LastY = Doc.Y + #Pieces - 1
		Doc.X = #Doc.Lines[LastY] + 1
		Doc.Lines[LastY] = Doc.Lines[LastY] .. Tail
		Invalidate(Doc.Y)
		Doc.Y = LastY
	end
	Invalidate(Doc.Y)
	Doc.Modified = true
end

local function ViewSize()
	return Editor.W - Editor.Gutter, Editor.H
end

local function EnsureVisible()
	Clamp()
	local ViewW, ViewH = ViewSize()
	if (Doc.Y <= Doc.ScrollY) then Doc.ScrollY = Doc.Y - 1 end
	if (Doc.Y > Doc.ScrollY + ViewH) then Doc.ScrollY = Doc.Y - ViewH end
	local Column = DisplayWidth(Doc.Lines[Doc.Y], Doc.X - 1)
	if (Column < Doc.ScrollX) then Doc.ScrollX = math.max(0, Column - 4) end
	if (Column >= Doc.ScrollX + ViewW - 1) then Doc.ScrollX = Column - ViewW + 2 end
end

local function SetLines(Text)
	Doc.Lines = {}
	for Line in (Text:gsub("\r\n", "\n") .. "\n"):gmatch("(.-)\n") do
		table.insert(Doc.Lines, Line)
	end
	if (#Doc.Lines > 1 and Doc.Lines[#Doc.Lines] == "") then
		table.remove(Doc.Lines)
	end
	if (#Doc.Lines == 0) then Doc.Lines = { "" } end
	Doc.UseTabs = false
	for _, Line in ipairs(Doc.Lines) do
		if (Line:sub(1, 1) == "\t") then
			Doc.UseTabs = true
			break
		end
	end
	Doc.X, Doc.Y, Doc.ScrollX, Doc.ScrollY = 1, 1, 0, 0
	Doc.Anchor = nil
	Doc.Undo, Doc.Redo = {}, {}
	Doc.Modified = false
	Invalidate(1)
end

local function UpdateTitle()
	BlockOS.SetTitle((Doc.Modified and "\7 " or "") .. (Doc.Path and fs.getName(Doc.Path) or "Untitled"))
end

local function LoadFile(Path)
	local Text = Config.ReadText(Path)
	if (not Text) then
		SetLines("")
		Doc.Path = Path
		SetMessage("New file")
	else
		SetLines(Text)
		Doc.Path = Path
		SetMessage("Opened " .. fs.getName(Path))
	end
	UpdateTitle()
end

local function SaveAs()
	local Path = Ui.PickFile({ Save = true, Dir = Doc.Path and fs.getDir(Doc.Path) or "/home/Documents", Name = Doc.Path and fs.getName(Doc.Path) or "untitled.lua" })
	if (not Path) then return false end
	Doc.Path = Path
	return true
end

local function Save()
	if (not Doc.Path and not SaveAs()) then return false end
	if (fs.isReadOnly(Doc.Path)) then
		Ui.Alert("Save", "This location is read-only.")
		return false
	end
	if (not Config.WriteText(Doc.Path, table.concat(Doc.Lines, "\n") .. "\n")) then
		Ui.Alert("Save", "Could not write " .. Doc.Path)
		return false
	end
	Doc.Modified = false
	SetMessage("Saved " .. fs.getName(Doc.Path))
	UpdateTitle()
	return true
end

-- Returns true when it is safe to discard the current document.
local function ConfirmDiscard()
	if (not Doc.Modified) then return true end
	local Choice = Ui.Alert("Unsaved changes", "Save changes to " .. (Doc.Path and fs.getName(Doc.Path) or "Untitled") .. "?", { "Cancel", "Don't Save", "Save" })
	if (Choice == 3) then return Save() end
	return Choice == 2
end

local function Run()
	if (not Save()) then return end
	BlockOS.Launch(Doc.Path, {}, { Hold = true })
end

local function FindNext(Query, FromStart)
	if (not Query or #Query == 0) then return false end
	local StartY, StartX = Doc.Y, Doc.X
	if (FromStart) then StartY, StartX = 1, 1 end
	for Offset = 0, #Doc.Lines do
		local Line = ((StartY - 1 + Offset) % #Doc.Lines) + 1
		local From = (Offset == 0) and StartX or 1
		local Start, Finish = Doc.Lines[Line]:find(Query, From, true)
		if (Start) then
			Doc.Anchor = { X = Start, Y = Line }
			Doc.X, Doc.Y = Finish + 1, Line
			EnsureVisible()
			return true
		end
	end
	SetMessage("Not found: " .. Query)
	return false
end

local function Indentation(Line)
	return Line:match("^[ \t]*")
end

local function IndentUnit()
	return Doc.UseTabs and "\t" or "  "
end

local function NewLine()
	PushUndo("edit")
	local Line = Doc.Lines[Doc.Y]:sub(1, Doc.X - 1)
	local Indent = Indentation(Doc.Lines[Doc.Y])
	local Trimmed = Line:gsub("%s+$", "")
	if (Trimmed:match("then$") or Trimmed:match("do$") or Trimmed:match("else$") or Trimmed:match("repeat$")
		or Trimmed:match("function%s*[%w_.:]*%b()$") or Trimmed:match("[{(]$")) then
		Indent = Indent .. IndentUnit()
	end
	InsertText("\n" .. Indent)
end

local function Move(Key)
	local Line = Doc.Lines[Doc.Y]
	local _, ViewH = ViewSize()
	if (Key == keys.left) then
		if (Modifiers.Ctrl) then
			local Before = Line:sub(1, Doc.X - 1)
			local Position = Before:find("[%w_]+[^%w_]*$") or 1
			Doc.X = (Position == Doc.X) and math.max(1, Doc.X - 1) or Position
		elseif (Doc.X > 1) then
			Doc.X = Doc.X - 1
		elseif (Doc.Y > 1) then
			Doc.Y = Doc.Y - 1
			Doc.X = #Doc.Lines[Doc.Y] + 1
		end
	elseif (Key == keys.right) then
		if (Modifiers.Ctrl) then
			local _, Finish = Line:find("^[^%w_]*[%w_]*", Doc.X)
			Doc.X = (Finish or #Line) + 1
		elseif (Doc.X <= #Line) then
			Doc.X = Doc.X + 1
		elseif (Doc.Y < #Doc.Lines) then
			Doc.Y = Doc.Y + 1
			Doc.X = 1
		end
	elseif (Key == keys.up or Key == keys.down or Key == keys.pageUp or Key == keys.pageDown) then
		local Column = DisplayWidth(Line, Doc.X - 1)
		local Step = ({ [keys.up] = -1, [keys.down] = 1, [keys.pageUp] = -ViewH, [keys.pageDown] = ViewH })[Key]
		Doc.Y = math.max(1, math.min(#Doc.Lines, Doc.Y + Step))
		Doc.X = CharFromDisplay(Doc.Lines[Doc.Y], Column)
	elseif (Key == keys.home) then
		if (Modifiers.Ctrl) then
			Doc.Y = 1
			Doc.X = 1
		else
			local Indent = #Indentation(Line) + 1
			Doc.X = (Doc.X == Indent) and 1 or Indent
		end
	elseif (Key == keys["end"]) then
		if (Modifiers.Ctrl) then Doc.Y = #Doc.Lines end
		Doc.X = #Doc.Lines[Doc.Y] + 1
	else
		return false
	end
	return true
end

--
-- Commands
--

local Clipboard = nil

local function Copy(Cut)
	local Text = SelectedText()
	if (not Text) then
		Text = Doc.Lines[Doc.Y] .. "\n"
		if (Cut) then
			PushUndo("edit")
			if (#Doc.Lines > 1) then
				table.remove(Doc.Lines, Doc.Y)
			else
				Doc.Lines[1] = ""
			end
			Doc.Modified = true
			Invalidate(Doc.Y)
		end
	elseif (Cut) then
		PushUndo("edit")
		DeleteSelection()
	end
	Clipboard = Text
	BlockOS.TextClipboard = Text
	SetMessage(Cut and "Cut" or "Copied")
end

local function PasteInternal()
	local Text = BlockOS.TextClipboard or Clipboard
	if (not Text) then return end
	PushUndo("edit")
	InsertText(Text)
end

local function UndoStep(Reverse)
	local From, To = Doc.Undo, Doc.Redo
	if (Reverse) then From, To = Doc.Redo, Doc.Undo end
	local Shot = table.remove(From)
	if (not Shot) then return end
	table.insert(To, Snapshot())
	Restore(Shot)
	Doc.Modified = true
	LastUndoKind = nil
end

local function ReplaceAll()
	local Query = Ui.Prompt("Replace", "Find:", Find)
	if (not Query or #Query == 0) then return end
	local Replacement = Ui.Prompt("Replace", "Replace with:", "")
	if (not Replacement) then return end
	PushUndo("edit")
	local Count = 0
	local Pattern = Query:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")
	local Safe = Replacement:gsub("%%", "%%%%")
	for Index, Line in ipairs(Doc.Lines) do
		local Updated, Hits = Line:gsub(Pattern, Safe)
		Doc.Lines[Index] = Updated
		Count = Count + Hits
	end
	Find = Query
	Doc.Modified = Count > 0 or Doc.Modified
	Invalidate(1)
	SetMessage("Replaced " .. Count .. " occurrence" .. (Count == 1 and "" or "s"))
end

local function GoToLine()
	local Value = tonumber(Ui.Prompt("Go to Line", "Line number (1-" .. #Doc.Lines .. "):", tostring(Doc.Y)) or "")
	if (Value) then
		Doc.Y = math.floor(Value)
		Doc.X = 1
		Doc.Anchor = nil
		EnsureVisible()
	end
end

local function NewDocument()
	if (not ConfirmDiscard()) then return end
	SetLines("")
	Doc.Path = nil
	UpdateTitle()
end

local function OpenDocument()
	if (not ConfirmDiscard()) then return end
	local Path = Ui.PickFile({ Dir = Doc.Path and fs.getDir(Doc.Path) or "/home/Documents" })
	if (Path) then LoadFile(Path) end
end

local function Close()
	if (ConfirmDiscard()) then
		BlockOS.Quit()
		Page:Stop()
	end
end

local function FileMenu()
	local Options = { "New", "Open...", "Save", "Save As...", "-", "Run", "-", "Close" }
	local Choice = Options[Ui.ContextMenu(1, 2, Options) or 0]
	if (Choice == "New") then
		NewDocument()
	elseif (Choice == "Open...") then
		OpenDocument()
	elseif (Choice == "Save") then
		Save()
	elseif (Choice == "Save As...") then
		if (SaveAs()) then Save() end
	elseif (Choice == "Run") then
		Run()
	elseif (Choice == "Close") then
		Close()
	end
end

local function EditMenu()
	local Options = { "Undo", "Redo", "-", "Cut", "Copy", "Paste", "Select All", "-", "Find...", "Find Next", "Replace...", "Go to Line..." }
	local Choice = Options[Ui.ContextMenu(7, 2, Options) or 0]
	if (Choice == "Undo") then
		UndoStep(false)
	elseif (Choice == "Redo") then
		UndoStep(true)
	elseif (Choice == "Cut" or Choice == "Copy") then
		Copy(Choice == "Cut")
	elseif (Choice == "Paste") then
		PasteInternal()
	elseif (Choice == "Select All") then
		Doc.Anchor = { X = 1, Y = 1 }
		Doc.Y = #Doc.Lines
		Doc.X = #Doc.Lines[Doc.Y] + 1
	elseif (Choice == "Find...") then
		local Query = Ui.Prompt("Find", "Search for:", Find)
		if (Query) then
			Find = Query
			FindNext(Find)
		end
	elseif (Choice == "Find Next") then
		FindNext(Find)
	elseif (Choice == "Replace...") then
		ReplaceAll()
	elseif (Choice == "Go to Line...") then
		GoToLine()
	end
	EnsureVisible()
end

--
-- Editor widget
--

local function DrawEditor(Self, T, Th)
	local P = Palette(Th)
	local Digits = #tostring(#Doc.Lines)
	Self.Gutter = Digits + 2
	local ViewW = Self.W - Self.Gutter
	local AX, AY, BX, BY = SelectionRange()
	for Row = 1, Self.H do
		local LineIndex = Doc.ScrollY + Row
		local Y = Self.Y + Row - 1
		local Line = Doc.Lines[LineIndex]
		if (not Line) then
			Gfx.Fill(T, Self.X, Y, Self.Gutter, 1, P.Gutter)
			Gfx.Fill(T, Self.X + Self.Gutter, Y, ViewW, 1, P.Bg)
		else
			local Number = Gfx.Pad(tostring(LineIndex), Digits, "right") .. " "
			Gfx.Write(T, Self.X, Y, " " .. Number, (LineIndex == Doc.Y) and P.Text or P.GutterFg, P.Gutter)
			local Colors = Highlight(Line, StateAt(LineIndex, P), P)
			local Chars, Fg, Bg = {}, {}, {}
			local BgCode, SelCode = Hex[P.Bg], Hex[P.Selection]
			for Index = 1, #Line do
				local Char = Line:sub(Index, Index)
				local Selected = AX and (LineIndex > AY or (LineIndex == AY and Index >= AX)) and (LineIndex < BY or (LineIndex == BY and Index < BX))
				local Code = Colors:sub(Index, Index)
				if (Code == "") then Code = Hex[P.Text] end
				if (Char == "\t") then
					for _ = 1, TabWidth() do
						table.insert(Chars, " ")
						table.insert(Fg, Code)
						table.insert(Bg, Selected and SelCode or BgCode)
					end
				else
					table.insert(Chars, Char)
					table.insert(Fg, Code)
					table.insert(Bg, Selected and SelCode or BgCode)
				end
			end
			local Text = table.concat(Chars):sub(Doc.ScrollX + 1, Doc.ScrollX + ViewW)
			local FgText = table.concat(Fg):sub(Doc.ScrollX + 1, Doc.ScrollX + ViewW)
			local BgText = table.concat(Bg):sub(Doc.ScrollX + 1, Doc.ScrollX + ViewW)
			local Padding = ViewW - #Text
			T.setCursorPos(Self.X + Self.Gutter, Y)
			T.blit(Text .. string.rep(" ", Padding), FgText .. string.rep(Hex[P.Text], Padding), BgText .. string.rep(BgCode, Padding))
		end
	end
end

local function EditorCursor(Self)
	local Row = Doc.Y - Doc.ScrollY
	if (Row < 1 or Row > Self.H) then return nil end
	local Column = DisplayWidth(Doc.Lines[Doc.Y], Doc.X - 1) - Doc.ScrollX
	if (Column < 0 or Column >= Self.W - Self.Gutter) then return nil end
	local Th = BlockOS.Require("theme").Get()
	return Self.X + Self.Gutter + Column, Self.Y + Row - 1, Palette(Th).Text
end

local function PositionFromMouse(Self, X, Y)
	local LineIndex = math.max(1, math.min(#Doc.Lines, Doc.ScrollY + Y - Self.Y + 1))
	local Column = math.max(0, X - Self.X - Self.Gutter + Doc.ScrollX)
	return CharFromDisplay(Doc.Lines[LineIndex], Column), LineIndex
end

local function EditorEvent(Self, Name, A, B, C)
	if (Name == "mouse_click" or Name == "mouse_drag") then
		local X, Y = PositionFromMouse(Self, B, C)
		if (Name == "mouse_click") then
			if (A == 2) then
				EditMenu()
				return true
			end
			Doc.Anchor = Modifiers.Shift and (Doc.Anchor or { X = Doc.X, Y = Doc.Y }) or { X = X, Y = Y }
		end
		Doc.X, Doc.Y = X, Y
		EnsureVisible()
		return true
	elseif (Name == "mouse_up") then
		if (Doc.Anchor and Doc.Anchor.X == Doc.X and Doc.Anchor.Y == Doc.Y) then
			Doc.Anchor = nil
		end
		return true
	elseif (Name == "mouse_scroll") then
		Doc.ScrollY = math.max(0, math.min(Doc.ScrollY + A * 3, math.max(0, #Doc.Lines - Self.H)))
		return true
	elseif (Name == "char") then
		if (Modifiers.Ctrl) then return true end
		PushUndo((A == " ") and "space" or "type")
		InsertText(A)
		EnsureVisible()
		return true
	elseif (Name == "paste") then
		PushUndo("edit")
		InsertText(A)
		EnsureVisible()
		return true
	elseif (Name == "key") then
		if (Modifiers.Ctrl) then
			if (A == keys.s) then
				Save()
			elseif (A == keys.o) then
				OpenDocument()
			elseif (A == keys.n) then
				NewDocument()
			elseif (A == keys.z) then
				UndoStep(false)
			elseif (A == keys.y) then
				UndoStep(true)
			elseif (A == keys.c or A == keys.x) then
				Copy(A == keys.x)
			elseif (A == keys.a) then
				Doc.Anchor = { X = 1, Y = 1 }
				Doc.Y = #Doc.Lines
				Doc.X = #Doc.Lines[Doc.Y] + 1
			elseif (A == keys.f) then
				local Query = Ui.Prompt("Find", "Search for:", Find)
				if (Query) then
					Find = Query
					FindNext(Find)
				end
			elseif (A == keys.h) then
				ReplaceAll()
			elseif (A == keys.g) then
				GoToLine()
			elseif (A == keys.d) then
				PushUndo("edit")
				table.insert(Doc.Lines, Doc.Y + 1, Doc.Lines[Doc.Y])
				Doc.Y = Doc.Y + 1
				Doc.Modified = true
				Invalidate(Doc.Y)
			elseif (A == keys.q or A == keys.w) then
				Close()
			elseif (not Move(A)) then
				return false
			elseif (not Modifiers.Shift) then
				Doc.Anchor = nil
			end
			EnsureVisible()
			return true
		end
		local Before = { X = Doc.X, Y = Doc.Y }
		if (Move(A)) then
			if (Modifiers.Shift) then
				Doc.Anchor = Doc.Anchor or Before
			else
				Doc.Anchor = nil
			end
		elseif (A == keys.enter or A == keys.numPadEnter) then
			NewLine()
		elseif (A == keys.backspace) then
			PushUndo("delete")
			if (not DeleteSelection()) then
				if (Doc.X > 1) then
					local Line = Doc.Lines[Doc.Y]
					local Unit = IndentUnit()
					if (Line:sub(1, Doc.X - 1):match("^%s+$") and Line:sub(Doc.X - #Unit, Doc.X - 1) == Unit) then
						Doc.Lines[Doc.Y] = Line:sub(1, Doc.X - #Unit - 1) .. Line:sub(Doc.X)
						Doc.X = Doc.X - #Unit
					else
						Doc.Lines[Doc.Y] = Line:sub(1, Doc.X - 2) .. Line:sub(Doc.X)
						Doc.X = Doc.X - 1
					end
				elseif (Doc.Y > 1) then
					local Previous = Doc.Lines[Doc.Y - 1]
					Doc.Lines[Doc.Y - 1] = Previous .. Doc.Lines[Doc.Y]
					table.remove(Doc.Lines, Doc.Y)
					Doc.Y = Doc.Y - 1
					Doc.X = #Previous + 1
				end
				Doc.Modified = true
				Invalidate(Doc.Y)
			end
		elseif (A == keys.delete) then
			PushUndo("delete")
			if (not DeleteSelection()) then
				local Line = Doc.Lines[Doc.Y]
				if (Doc.X <= #Line) then
					Doc.Lines[Doc.Y] = Line:sub(1, Doc.X - 1) .. Line:sub(Doc.X + 1)
				elseif (Doc.Y < #Doc.Lines) then
					Doc.Lines[Doc.Y] = Line .. Doc.Lines[Doc.Y + 1]
					table.remove(Doc.Lines, Doc.Y + 1)
				end
				Doc.Modified = true
				Invalidate(Doc.Y)
			end
		elseif (A == keys.tab) then
			PushUndo("edit")
			InsertText(IndentUnit())
		elseif (A == keys.f3) then
			FindNext(Find)
		elseif (A == keys.f5) then
			Run()
		else
			return false
		end
		EnsureVisible()
		return true
	end
	return false
end

function Page:OnLayout(W, H)
	self:Clear()
	self:Add(Ui.Panel.new({ X = 1, Y = 1, W = W, H = 1, Bg = "Panel" }))
	self:Add(Ui.Button.new({ X = 1, Y = 1, Text = "File", Bg = "Panel", OnClick = function() FileMenu() end }))
	self:Add(Ui.Button.new({ X = 7, Y = 1, Text = "Edit", Bg = "Panel", OnClick = function() EditMenu() end }))
	self:Add(Ui.Button.new({ X = W - 13, Y = 1, W = 6, Text = "Save", Bg = "Panel", OnClick = function() Save() end }))
	self:Add(Ui.Button.new({ X = W - 6, Y = 1, W = 7, Text = "Run \16", Style = "primary", OnClick = function() Run() end }))
	Editor = self:Add(Ui.Canvas.new({
		X = 1, Y = 2, W = W, H = H - 2, Gutter = 3, Focusable = true, KeepFocus = true,
		OnDraw = DrawEditor,
		OnEvent = EditorEvent,
		OnCursor = EditorCursor
	}))
	self:Add(Ui.Canvas.new({
		X = 1, Y = H, W = W, H = 1,
		OnDraw = function(Self, T, Th)
			local Left = " Ln " .. Doc.Y .. ", Col " .. Doc.X .. (Doc.Modified and "  \7 Edited" or "")
			local Right = (IsLua() and "Lua" or "Text") .. " "
			if (Message and os.clock() - MessageTime < 4) then
				Right = Message .. "  " .. Right
			end
			Gfx.Write(T, Self.X, Self.Y, Gfx.Pad(Left, Self.W - #Right) .. Right, Th.SubText, Th.Panel)
		end
	}))
	self:SetFocus(Editor)
	EnsureVisible()
end

function Page:OnEvent(Name, A)
	if (Name == "blockos_close") then
		Close()
		return true
	elseif (Name == "blockos_open" and A) then
		if (ConfirmDiscard()) then LoadFile(A) end
		return true
	end
	return false
end

function Page:OnTerminate()
	Close()
end

local BaseHandle = Page.Handle
function Page:Handle(...)
	BaseHandle(self, ...)
	if (Doc.Modified ~= self.LastModified) then
		self.LastModified = Doc.Modified
		UpdateTitle()
	end
end

BlockOS.SetCloseHandler(true)
if (Args[1]) then
	LoadFile(shell and shell.resolve(Args[1]) or Args[1])
else
	UpdateTitle()
end
Page:SetInterval(1, function()
	return Message ~= nil
end)
Page:Run()
]=]
Files["blockos/apps/finder/app.cfg"] = [[
{ Name = "Finder", Description = "Browse files, folders, disks and apps.", Width = 44, Height = 14, Icon = { Lines = { " :)", "\140\140\140" }, Fg = "white", Bg = "blue" } }
]]
Files["blockos/apps/finder/main.lua"] = [[
-- Finder: file manager with favourites, disks and an Applications view.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Apps = BlockOS.Require("apps")

local Args = { ... }

local AppsPath = "apps:"
local Printable = { txt = true, md = true, log = true }
local Current = Args[1] or "/home"
local Back, Forward = {}, {}
local Page = Ui.Page.new()
local Sidebar, Files, PathLabel, Status

BlockOS.Clipboard = BlockOS.Clipboard or {}

local Kinds = {
	lua = { Icon = "\4", Fg = colors.yellow, Name = "Lua script" },
	txt = { Icon = "\7", Fg = colors.lightGray, Name = "Text" },
	md = { Icon = "\7", Fg = colors.lightGray, Name = "Markdown" },
	dfpwm = { Icon = "\14", Fg = colors.red, Name = "DFPWM audio" },
	rec = { Icon = "\7", Fg = colors.red, Name = "Recording" },
	nfp = { Icon = "\127", Fg = colors.pink, Name = "Paint image" },
	json = { Icon = "\7", Fg = colors.orange, Name = "JSON" },
	cfg = { Icon = "\7", Fg = colors.orange, Name = "Config" }
}

local function Normalize(Path)
	if (Path == AppsPath) then return Path end
	return "/" .. fs.combine(Path, "")
end

local function KindOf(Path)
	if (fs.isDir(Path)) then
		return { Icon = "\16", Fg = colors.lightBlue, Name = "Folder" }
	end
	local Extension = Path:match("%.([%w]+)$")
	return Kinds[Extension and Extension:lower() or ""] or { Icon = "\7", Fg = colors.gray, Name = "File" }
end

local function DisplayName(Path)
	if (Path == AppsPath) then return "Applications" end
	if (Path == "/") then return "Computer" end
	if (Path == "/home") then return "Home" end
	return fs.getName(Path)
end

local function UniqueName(Dir, Name)
	if (not fs.exists(fs.combine(Dir, Name))) then return Name end
	local Base, Extension = Name:match("^(.-)(%.[^%.]*)$")
	if (not Base or Base == "") then
		Base, Extension = Name, ""
	end
	local Index = 1
	while (true) do
		local Candidate = Base .. " copy" .. (Index > 1 and (" " .. Index) or "") .. Extension
		if (not fs.exists(fs.combine(Dir, Candidate))) then return Candidate end
		Index = Index + 1
	end
end

local function SidebarItems()
	local Items = {
		{ Text = "Favorites", Header = true },
		{ Text = "Home", Path = "/home", Icon = "\127", IconFg = colors.lightBlue },
		{ Text = "Documents", Path = "/home/Documents", Icon = "\7", IconFg = colors.lightBlue },
		{ Text = "Downloads", Path = "/home/Downloads", Icon = "\25", IconFg = colors.lightBlue },
		{ Text = "Music", Path = "/home/Music", Icon = "\14", IconFg = colors.lightBlue },
		{ Text = "Recordings", Path = "/home/Recordings", Icon = "\7", IconFg = colors.red },
		{ Text = "Locations", Header = true },
		{ Text = "Apps", Path = AppsPath, Icon = "\4", IconFg = colors.purple },
		{ Text = "Computer", Path = "/", Icon = "\8", IconFg = colors.gray }
	}
	for _, Side in ipairs(peripheral.getNames()) do
		if (peripheral.getType(Side) == "drive" and disk.hasData(Side)) then
			local Mount = disk.getMountPath(Side)
			table.insert(Items, { Text = disk.getLabel(Side) or Mount, Path = "/" .. Mount, Icon = "\22", IconFg = colors.gray, Side = Side })
		end
	end
	return Items
end

local Refresh

local function Navigate(Path, SkipHistory)
	Path = Normalize(Path)
	if (Path ~= AppsPath and not fs.isDir(Path)) then
		BlockOS.Open(Path)
		return
	end
	if (not SkipHistory and Path ~= Current) then
		table.insert(Back, Current)
		Forward = {}
	end
	Current = Path
	Refresh()
end

local function OpenItem(Item)
	if (not Item) then return end
	if (Item.App) then
		BlockOS.Launch(Item.App.ID)
	elseif (Item.IsDir) then
		Navigate(Item.Path)
	else
		BlockOS.Open(Item.Path)
	end
end

function Refresh()
	local Items = {}
	if (Current == AppsPath) then
		for _, App in ipairs(Apps.List()) do
			table.insert(Items, {
				Text = App.Name,
				Icon = Gfx.Pad(App.Icon.Lines[1], 3),
				IconFg = App.Icon.Bg,
				Right = App.System and "System" or "Installed",
				App = App
			})
		end
	else
		if (not fs.isDir(Current)) then Current = "/" end
		local Names = fs.list(Current)
		table.sort(Names, function(A, B) return A:lower() < B:lower() end)
		local Dirs, Plain = {}, {}
		for _, Name in ipairs(Names) do
			local Path = fs.combine(Current, Name)
			local Kind = KindOf(Path)
			local Entry = { Text = Name, Icon = Kind.Icon, IconFg = Kind.Fg, Path = "/" .. Path, IsDir = fs.isDir(Path) }
			if (Entry.IsDir) then
				Entry.Right = "--"
				table.insert(Dirs, Entry)
			else
				Entry.Right = Gfx.FormatSize(fs.getSize(Path))
				table.insert(Plain, Entry)
			end
		end
		for _, Entry in ipairs(Dirs) do table.insert(Items, Entry) end
		for _, Entry in ipairs(Plain) do table.insert(Items, Entry) end
	end
	Files:SetItems(Items)
	local SideItems = SidebarItems()
	Sidebar:SetItems(SideItems, true)
	Sidebar.Selected = 0
	for Index, Item in ipairs(SideItems) do
		if (Item.Path == Current) then Sidebar.Selected = Index end
	end
	PathLabel.Text = DisplayName(Current)
	if (Current == AppsPath) then
		Status.Text = #Items .. " apps"
	else
		Status.Text = #Items .. " items, " .. Gfx.FormatSize(fs.getFreeSpace(Current)) .. " free" .. (fs.isReadOnly(Current) and ", read-only" or "")
	end
	BlockOS.SetTitle(DisplayName(Current))
	Page:Invalidate()
end

local function Paste(Dir)
	local Clip = BlockOS.Clipboard
	if (not Clip.Path or not fs.exists(Clip.Path) or Dir == AppsPath) then return end
	local Target = fs.combine(Dir, UniqueName(Dir, fs.getName(Clip.Path)))
	local Ok, Err = pcall(function()
		if (Clip.Cut) then
			fs.move(Clip.Path, Target)
		else
			fs.copy(Clip.Path, Target)
		end
	end)
	if (not Ok) then
		Ui.Alert("Paste failed", tostring(Err))
	end
	if (Clip.Cut) then BlockOS.Clipboard = {} end
	Refresh()
end

local function NewItem(Folder)
	if (Current == AppsPath or fs.isReadOnly(Current)) then return end
	local Name = Ui.Prompt(Folder and "New Folder" or "New File", "Name:", Folder and "untitled folder" or "untitled.txt")
	if (not Name or #Name == 0) then return end
	local Path = fs.combine(Current, UniqueName(Current, Name))
	if (Folder) then
		fs.makeDir(Path)
	else
		local Handle = fs.open(Path, "w")
		if (Handle) then Handle.close() end
	end
	Refresh()
end

local function DeleteItem(Item)
	if (not Item or not Item.Path or fs.isReadOnly(Item.Path)) then return end
	if (Ui.Confirm("Delete", "Delete \"" .. fs.getName(Item.Path) .. "\"? This cannot be undone.", "Delete")) then
		local Ok, Err = pcall(fs.delete, Item.Path)
		if (not Ok) then Ui.Alert("Delete failed", tostring(Err)) end
		Refresh()
	end
end

local function GetInfo(Item)
	if (Item.App) then
		local App = Item.App
		Ui.Alert(App.Name, (App.Description or "No description.") .. "\n\nID: " .. App.ID .. "\nLocation: " .. App.Dir)
		return
	end
	local Path = Item.Path
	local Lines = { "Kind: " .. KindOf(Path).Name, "Where: " .. fs.getDir(Path) }
	if (not Item.IsDir) then
		table.insert(Lines, "Size: " .. Gfx.FormatSize(fs.getSize(Path)))
	end
	if (fs.attributes) then
		local Ok, Attributes = pcall(fs.attributes, Path)
		if (Ok and Attributes.modified and Attributes.modified > 0) then
			table.insert(Lines, "Modified: " .. os.date("%Y-%m-%d %H:%M", math.floor(Attributes.modified / 1000)))
		end
	end
	table.insert(Lines, fs.isReadOnly(Path) and "Read-only" or "Writable")
	Ui.Alert(fs.getName(Path), table.concat(Lines, "\n"))
end

local function AppMenu(Item, X, Y)
	local App = Item.App
	local Pinned = Apps.IsPinned(App.ID)
	local Options = { "Open", "Open Full Screen", "-", Pinned and "Remove from Dock" or "Keep in Dock", "Add to Login Items", "Get Info" }
	if (not App.System) then
		table.insert(Options, "-")
		table.insert(Options, "Uninstall")
	end
	local Choice = Options[Ui.ContextMenu(X, Y, Options) or 0]
	if (Choice == "Open") then
		BlockOS.Launch(App.ID)
	elseif (Choice == "Open Full Screen") then
		BlockOS.Launch(App.ID, {}, { Mode = "fullscreen" })
	elseif (Choice == "Keep in Dock" or Choice == "Remove from Dock") then
		Apps.SetPinned(App.ID, not Pinned)
	elseif (Choice == "Add to Login Items") then
		local Config = BlockOS.Require("config")
		local Settings = Config.Settings()
		table.insert(Settings.StartupApps, App.ID)
		Config.Save("settings")
	elseif (Choice == "Get Info") then
		GetInfo(Item)
	elseif (Choice == "Uninstall") then
		if (Ui.Confirm("Uninstall", "Remove " .. App.Name .. " from this computer?", "Uninstall")) then
			Apps.Uninstall(App.ID)
			Refresh()
		end
	end
end

local function FileMenu(Item, X, Y)
	local ReadOnly = Current == AppsPath or fs.isReadOnly(Current)
	local HasClip = BlockOS.Clipboard.Path ~= nil
	if (not Item) then
		local Options = {
			{ Text = "New Folder", Disabled = ReadOnly },
			{ Text = "New File", Disabled = ReadOnly },
			{ Text = "Paste", Disabled = ReadOnly or not HasClip },
			"-",
			{ Text = "Open in Terminal" },
			{ Text = "Refresh" }
		}
		local Index = Ui.ContextMenu(X, Y, Options)
		local Choice = Index and Options[Index].Text
		if (Choice == "New Folder") then
			NewItem(true)
		elseif (Choice == "New File") then
			NewItem(false)
		elseif (Choice == "Paste") then
			Paste(Current)
		elseif (Choice == "Open in Terminal") then
			BlockOS.Launch("terminal", { Current })
		elseif (Choice == "Refresh") then
			Refresh()
		end
		return
	end
	if (Item.App) then
		AppMenu(Item, X, Y)
		return
	end
	local Locked = fs.isReadOnly(Item.Path)
	local Options = {
		{ Text = "Open" },
		{ Text = "Edit", Disabled = Item.IsDir },
		{ Text = "Run", Disabled = Item.IsDir },
		"-",
		{ Text = "Rename", Disabled = Locked },
		{ Text = "Duplicate", Disabled = ReadOnly },
		{ Text = "Copy" },
		{ Text = "Cut", Disabled = Locked },
		{ Text = "Paste", Disabled = ReadOnly or not HasClip },
		"-",
		{ Text = "Get Info" },
		{ Text = "Delete", Disabled = Locked }
	}
	local Extension = (fs.getName(Item.Path):match("%.(%w+)$") or ""):lower()
	if (not Item.IsDir and Printable[Extension]) then
		table.insert(Options, 4, { Text = "Print" })
	end
	local Index = Ui.ContextMenu(X, Y, Options)
	local Choice = Index and Options[Index].Text
	if (Choice == "Open") then
		OpenItem(Item)
	elseif (Choice == "Edit") then
		BlockOS.Launch("editor", { Item.Path })
	elseif (Choice == "Run") then
		BlockOS.Launch(Item.Path, {}, { Hold = true })
	elseif (Choice == "Print") then
		BlockOS.Launch("print", { Item.Path })
	elseif (Choice == "Rename") then
		local Name = Ui.Prompt("Rename", "New name:", fs.getName(Item.Path))
		if (Name and #Name > 0 and Name ~= fs.getName(Item.Path)) then
			local Target = fs.combine(fs.getDir(Item.Path), Name)
			if (fs.exists(Target)) then
				Ui.Alert("Rename", "An item with that name already exists.")
			else
				fs.move(Item.Path, Target)
			end
		end
		Refresh()
	elseif (Choice == "Duplicate") then
		fs.copy(Item.Path, fs.combine(Current, UniqueName(Current, fs.getName(Item.Path))))
		Refresh()
	elseif (Choice == "Copy" or Choice == "Cut") then
		BlockOS.Clipboard = { Path = Item.Path, Cut = Choice == "Cut" }
	elseif (Choice == "Paste") then
		Paste(Item.IsDir and Item.Path or Current)
	elseif (Choice == "Get Info") then
		GetInfo(Item)
	elseif (Choice == "Delete") then
		DeleteItem(Item)
	end
end

local function GoUp()
	if (Current == AppsPath or Current == "/") then return end
	Navigate("/" .. fs.getDir(Current))
end

function Page:OnLayout(W, H)
	self:Clear()
	local SideW = (W >= 34) and 12 or 0
	self:Add(Ui.Panel.new({ X = 1, Y = 1, W = W, H = 1, Bg = "Panel" }))
	self:Add(Ui.Button.new({ X = 1, Y = 1, W = 3, Text = "\17", Bg = "Panel", OnClick = function()
		if (#Back > 0) then
			table.insert(Forward, Current)
			Current = table.remove(Back)
			Refresh()
		end
	end }))
	self:Add(Ui.Button.new({ X = 4, Y = 1, W = 3, Text = "\16", Bg = "Panel", OnClick = function()
		if (#Forward > 0) then
			table.insert(Back, Current)
			Current = table.remove(Forward)
			Refresh()
		end
	end }))
	self:Add(Ui.Button.new({ X = 7, Y = 1, W = 3, Text = "\24", Bg = "Panel", OnClick = GoUp }))
	PathLabel = self:Add(Ui.Label.new({ X = 11, Y = 1, W = W - 18, Text = "", Bg = "Panel", Fg = "PanelFg" }))
	self:Add(Ui.Button.new({ X = W - 6, Y = 1, W = 3, Text = "+", Bg = "Panel", OnClick = function() NewItem(true) end }))
	self:Add(Ui.Button.new({ X = W - 3, Y = 1, W = 3, Text = "\15", Bg = "Panel", OnClick = function() FileMenu(nil, W - 3, 2) end }))
	Sidebar = self:Add(Ui.List.new({ X = 1, Y = 2, W = SideW, H = H - 2, Bg = "Panel", Focusable = false, SingleClick = true, Visible = SideW > 0 }))
	Sidebar.RenderItem = function(_, T, Th, Item, X, Y, Width, Selected, RowBg, RowFg)
		if (Item.Header) then
			Gfx.Write(T, X, Y, Gfx.Pad(Item.Text, Width), Th.SubText, Th.Panel)
			return
		end
		Gfx.Write(T, X, Y, " " .. (Item.Icon or " ") .. " " .. Gfx.Truncate(Item.Text, Width - 4), Selected and RowFg or Th.PanelFg, RowBg)
		if (not Selected) then
			Gfx.Write(T, X + 1, Y, Item.Icon or " ", Item.IconFg or Th.PanelFg, RowBg)
		end
	end
	Sidebar.OnActivate = function(_, _, Item)
		if (Item.Header) then return end
		Navigate(Item.Path)
	end
	Sidebar.OnContext = function(_, _, Item, X, Y)
		if (Item and Item.Side) then
			local Choice = Ui.ContextMenu(X, Y, { "Open", "Eject" })
			if (Choice == 1) then
				Navigate(Item.Path)
			elseif (Choice == 2) then
				disk.eject(Item.Side)
			end
		end
	end
	Files = self:Add(Ui.List.new({ X = SideW + 1, Y = 2, W = W - SideW, H = H - 2 }))
	Files.OnActivate = function(_, _, Item) OpenItem(Item) end
	Files.OnContext = function(_, _, Item, X, Y) FileMenu(Item, X, Y) end
	Status = self:Add(Ui.Label.new({ X = 1, Y = H, W = W, Text = "", Bg = "Panel", Fg = "SubText", Align = "center" }))
	self:SetFocus(Files)
	Refresh()
end

function Page:OnEvent(Name, A)
	if (Name == "key") then
		if (A == keys.backspace) then
			GoUp()
			return true
		elseif (A == keys.delete) then
			DeleteItem(Files.Items[Files.Selected])
			return true
		end
	elseif (Name == "disk" or Name == "disk_eject" or Name == "blockos_apps" or Name == "peripheral" or Name == "peripheral_detach") then
		Refresh()
		return true
	elseif (Name == "blockos_open") then
		Navigate(A)
		return true
	end
	return false
end

Current = Normalize(Current)
Page:Run()
]]
