Files["blockos/apps/network/main.lua"] = [[
-- Network: finds nearby BlockOS computers over rednet and places them on a map using GPS.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Config = BlockOS.Require("config")
local Presence = BlockOS.Require("presence")

local Page = Ui.Page.new()
local Settings = Config.Settings()

local ScanSeconds = 3
local RescanSeconds = 30
local RelocateSeconds = 60
local Scales = { 1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000, 10000 }
-- Terminal cells are about one and a half times taller than they are wide.
local CellAspect = 1.5

local State = {
	Computers = {},
	Self = nil,
	Status = "idle",
	Message = nil,
	Selected = nil,
	Scale = nil,
	ScanTimer = nil
}
local Markers = {}
local Build

local function Distance(Entry)
	if (not (State.Self and Entry.Position)) then return math.huge end
	return (Presence.Bearing(State.Self, Entry.Position))
end

local function Sorted()
	local List = {}
	for _, Entry in pairs(State.Computers) do
		table.insert(List, Entry)
	end
	table.sort(List, function(A, B)
		local DA, DB = Distance(A), Distance(B)
		if (DA ~= DB) then return DA < DB end
		return A.ID < B.ID
	end)
	return List
end

local function FormatDistance(Blocks)
	if (Blocks == math.huge) then return "?" end
	if (Blocks < 1000) then return string.format("%dm", math.floor(Blocks + .5)) end
	return string.format("%.1fkm", Blocks / 1000)
end

local function Scan()
	if (State.Status ~= "idle") then return end
	if (not Presence.OpenModems()) then
		State.Message = "No modem attached"
		Build()
		return
	end
	State.Message = nil
	if (not Presence.LocatedAt or os.clock() - Presence.LocatedAt > RelocateSeconds) then
		State.Status = "locating"
		Page:Draw()
		Presence.Locate(2)
	end
	State.Self = Presence.Position
	State.Computers = {}
	State.Status = "scanning"
	Presence.Scan()
	State.ScanTimer = os.startTimer(ScanSeconds)
	Build()
end

local function StatusText()
	if (State.Status == "locating") then return "Locating with GPS..." end
	if (State.Status == "scanning") then return "Scanning..." end
	if (State.Message) then return State.Message end
	local Count = 0
	for _ in pairs(State.Computers) do Count = Count + 1 end
	local Text = (Count == 1) and "1 computer nearby" or (Count .. " computers nearby")
	if (State.Self) then
		return Text .. string.format(" \7 you %d, %d, %d", State.Self.X, State.Self.Y, State.Self.Z)
	end
	return Text .. " \7 no GPS"
end

local function DetailText()
	local Entry = State.Selected and State.Computers[State.Selected]
	if (not Entry) then
		return Settings.NetworkVisible ~= false and "Select a computer for details." or "This computer is hidden from others."
	end
	local Parts = { "#" .. Entry.ID .. " " .. Presence.Name(Entry) }
	if (Entry.User) then table.insert(Parts, Entry.User) end
	if (State.Self and Entry.Position) then
		local Blocks, Direction = Presence.Bearing(State.Self, Entry.Position)
		table.insert(Parts, FormatDistance(Blocks) .. " " .. Direction)
		local Rise = Entry.Position.Y - State.Self.Y
		table.insert(Parts, "y" .. ((Rise >= 0) and "+" or "") .. Rise)
	elseif (Entry.Position) then
		table.insert(Parts, string.format("%d, %d, %d", Entry.Position.X, Entry.Position.Y, Entry.Position.Z))
	else
		table.insert(Parts, "no GPS")
	end
	return table.concat(Parts, " \7 ")
end

-- The point the map is centred on: this computer, or the middle of everyone else.
local function MapCentre()
	if (State.Self) then return State.Self end
	local SumX, SumZ, Count = 0, 0, 0
	for _, Entry in pairs(State.Computers) do
		if (Entry.Position) then
			SumX = SumX + Entry.Position.X
			SumZ = SumZ + Entry.Position.Z
			Count = Count + 1
		end
	end
	if (Count == 0) then return nil end
	return { X = SumX / Count, Y = 0, Z = SumZ / Count }
end

local function FitScale(Centre, W, H)
	local Needed = 1
	for _, Entry in pairs(State.Computers) do
		if (Entry.Position) then
			local DX = math.abs(Entry.Position.X - Centre.X) / math.max(1, W / 2 - 2)
			local DZ = math.abs(Entry.Position.Z - Centre.Z) / math.max(1, (H / 2 - 1) * CellAspect)
			Needed = math.max(Needed, DX, DZ)
		end
	end
	for _, Scale in ipairs(Scales) do
		if (Scale >= Needed) then return Scale end
	end
	return Scales[#Scales]
end

local function Zoom(Step)
	local Current = State.Scale or State.FittedScale or 1
	local Index = 1
	for Position, Scale in ipairs(Scales) do
		if (Scale <= Current) then Index = Position end
	end
	State.Scale = Scales[math.max(1, math.min(#Scales, Index + Step))]
end

local function DrawMap(Self, T, Th)
	local W, H = Self.W, Self.H
	Gfx.Fill(T, Self.X, Self.Y, W, H, Th.Panel)
	Markers = {}
	local Centre = MapCentre()
	if (not Centre) then
		local Hint = "No GPS signal. Build a GPS cluster (four computers running gps host) to see where everyone is."
		if (State.Message) then
			Hint = "Attach a wireless or ender modem to find nearby computers."
		end
		local Lines = Gfx.Wrap(Hint, W - 2)
		local Top = Self.Y + math.max(0, math.floor((H - #Lines) / 2))
		for Row, Line in ipairs(Lines) do
			if (Top + Row - 1 < Self.Y + H) then
				Gfx.Center(T, Top + Row - 1, Line, Th.SubText, Th.Panel, Self.X, W)
			end
		end
		return
	end
	State.FittedScale = FitScale(Centre, W, H)
	local Scale = State.Scale or State.FittedScale
	local MidX = Self.X + math.floor(W / 2)
	local MidY = Self.Y + math.floor(H / 2)
	for Row = 0, H - 1 do
		for Column = 0, W - 1 do
			if ((Self.X + Column - MidX) % 6 == 0 and (Self.Y + Row - MidY) % 3 == 0) then
				Gfx.Write(T, Self.X + Column, Self.Y + Row, "+", Th.Border, Th.Panel)
			end
		end
	end
	Gfx.Write(T, Self.X, Self.Y, "\24N", Th.SubText, Th.Panel)
	local Legend = "\140\140\140\140\140\140 " .. FormatDistance(Scale * 6)
	Gfx.Write(T, Self.X, Self.Y + H - 1, Legend, Th.SubText, Th.Panel)

	local function Plot(Position, Char, Fg, Bg, Label, ID)
		local X = MidX + math.floor((Position.X - Centre.X) / Scale + .5)
		local Y = MidY + math.floor((Position.Z - Centre.Z) / (Scale * CellAspect) + .5)
		local Outside = X < Self.X or X >= Self.X + W or Y < Self.Y or Y >= Self.Y + H
		X = math.max(Self.X, math.min(Self.X + W - 1, X))
		Y = math.max(Self.Y, math.min(Self.Y + H - 1, Y))
		Gfx.Write(T, X, Y, Outside and "\4" or Char, Outside and Th.SubText or Fg, Bg or Th.Panel)
		if (Label and X + 2 + #Label <= Self.X + W) then
			Gfx.Write(T, X + 1, Y, " " .. Label, Th.SubText, Th.Panel)
		end
		if (ID) then table.insert(Markers, { X = X, Y = Y, ID = ID }) end
	end

	for _, Entry in ipairs(Sorted()) do
		if (Entry.Position) then
			local Selected = Entry.ID == State.Selected
			Plot(Entry.Position, Entry.Turtle and "T" or "\7", Selected and Th.AccentFg or Th.Text, Selected and Th.Accent or nil, Gfx.Truncate(Presence.Name(Entry), 10), Entry.ID)
		end
	end
	if (State.Self) then
		Plot(State.Self, "\2", Th.Accent, nil, "You")
	end
end

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	Page:Add(Ui.Panel.new({ X = 1, Y = 1, W = W, H = 1, Bg = "Panel" }))
	Page:Add(Ui.Button.new({ X = 1, Y = 1, W = 6, Text = "Scan", Style = "primary", OnClick = Scan }))
	Page:Add(Ui.Label.new({ X = 8, Y = 1, W = W - 14, Text = StatusText, Fg = "SubText", Bg = "Panel" }))
	Page:Add(Ui.Button.new({ X = W - 5, Y = 1, W = 3, Text = "-", Bg = "Panel", OnClick = function() Zoom(1) end }))
	Page:Add(Ui.Button.new({ X = W - 2, Y = 1, W = 3, Text = "+", Bg = "Panel", OnClick = function() Zoom(-1) end }))

	local BodyH = math.max(3, H - 3)
	local ListW = (W >= 38) and 16 or 0
	local MapW = W - ((ListW > 0) and ListW + 1 or 0)
	Page:Add(Ui.Canvas.new({
		X = 1, Y = 2, W = MapW, H = BodyH,
		OnDraw = DrawMap,
		OnEvent = function(Self, Name, A, B, C)
			if (Name == "mouse_click") then
				for _, Marker in ipairs(Markers) do
					if (math.abs(Marker.X - B) <= 1 and Marker.Y == C) then
						State.Selected = Marker.ID
						Build()
						return true
					end
				end
			elseif (Name == "mouse_scroll") then
				Zoom(A)
				return true
			end
			return false
		end
	}))
	if (ListW > 0) then
		local Items = {}
		local Selected = 0
		for Index, Entry in ipairs(Sorted()) do
			table.insert(Items, {
				Text = Presence.Name(Entry), ID = Entry.ID,
				Icon = Entry.Turtle and "T" or "\7", IconFg = Entry.Position and "Accent" or "SubText",
				Right = FormatDistance(Distance(Entry))
			})
			if (Entry.ID == State.Selected) then Selected = Index end
		end
		local List = Page:Add(Ui.List.new({ X = MapW + 2, Y = 2, W = ListW, H = BodyH, Items = Items, Bg = "Panel" }))
		List.Selected = Selected
		List.OnSelect = function(_, _, Item)
			if (Item) then State.Selected = Item.ID end
		end
		if (#Items == 0 and State.Status == "idle") then
			Page:Add(Ui.Label.new({ X = MapW + 3, Y = 3, W = ListW - 2, H = 4, Fg = "SubText", Bg = "Panel", Text = "No other computers answered." }))
		end
	end

	Page:Add(Ui.Label.new({ X = 1, Y = H - 1, W = W, Text = DetailText }))
	Page:Add(Ui.Toggle.new({
		X = 1, Y = H, Value = Settings.NetworkVisible ~= false,
		OnChange = function(_, Value)
			Settings.NetworkVisible = Value
			Config.Save("settings")
		end
	}))
	Page:Add(Ui.Label.new({ X = 6, Y = H, W = W - 5, Text = "Let other computers find this one", Fg = "SubText" }))
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name, A, B, C)
	if (Name == "rednet_message" and C == Presence.Protocol) then
		local Entry = Presence.Parse(A, B)
		if (not Entry or A == os.getComputerID()) then return false end
		State.Computers[Entry.ID] = Entry
		Build()
		return true
	elseif (Name == "timer" and A == State.ScanTimer) then
		State.ScanTimer = nil
		State.Status = "idle"
		Build()
		return true
	elseif (Name == "peripheral" or Name == "peripheral_detach") then
		Build()
		return true
	end
	return false
end

Page:SetInterval(RescanSeconds, function()
	Scan()
	return false
end)

Page:Resize()
Scan()
Page:Run()
]]
Files["blockos/apps/notes/app.cfg"] = [[
{ Name = "Notes", Description = "Quick notes and plain text files with word wrap and autosave.", Width = 44, Height = 14, Single = true, Icon = { Lines = { "\140\140\140", "\140\140 " }, Fg = "black", Bg = "yellow" } }
]]
Files["blockos/apps/notes/main.lua"] = [[
-- Notes: a notepad with a list of notes, word wrap and autosave. Also opens .txt files.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Config = BlockOS.Require("config")

local Args = { ... }

local Folder = "/home/Notes"
local SaveDelay = 1.5

local Page = Ui.Page.new()
local Notes = {}
local Doc = nil
local Rows = {}
local Layout = { SideW = 0, EX = 1, EY = 2, EW = 10, EH = 5 }
local Build

local function SplitLines(Text)
	local Lines = {}
	for Line in ((Text or ""):gsub("\r", "") .. "\n"):gmatch("(.-)\n") do
		table.insert(Lines, Line)
	end
	if (#Lines == 0) then Lines[1] = "" end
	return Lines
end

local function TitleOf(Lines, Path)
	for _, Line in ipairs(Lines) do
		local Trimmed = Line:match("^%s*(.-)%s*$")
		if (#Trimmed > 0) then return Trimmed end
	end
	return Path and fs.getName(Path):gsub("%.txt$", "") or "New Note"
end

local function Modified(Path)
	local Ok, Attributes = pcall(fs.attributes, Path)
	return Ok and Attributes and Attributes.modified or 0
end

local function LoadNotes()
	if (not fs.exists(Folder)) then fs.makeDir(Folder) end
	Notes = {}
	for _, Name in ipairs(fs.list(Folder)) do
		local Path = "/" .. fs.combine(Folder, Name)
		if (Name:match("%.txt$") and not fs.isDir(Path)) then
			local Lines = SplitLines(Config.ReadText(Path))
			table.insert(Notes, { Path = Path, Title = TitleOf(Lines, Path), Modified = Modified(Path) })
		end
	end
	table.sort(Notes, function(A, B) return A.Modified > B.Modified end)
	if (Doc and Doc.Path and not Doc.Path:find("^" .. Folder .. "/")) then
		table.insert(Notes, 1, { Path = Doc.Path, Title = fs.getName(Doc.Path), External = true })
	end
end

local function WordCount()
	local Count = 0
	for _, Line in ipairs(Doc.Lines) do
		for _ in Line:gmatch("%S+") do Count = Count + 1 end
	end
	return Count
end

local function Save()
	if (not Doc or not Doc.Dirty) then return true end
	local Ok = Config.WriteText(Doc.Path, table.concat(Doc.Lines, "\n"))
	if (Ok) then
		Doc.Dirty = false
		for _, Note in ipairs(Notes) do
			if (Note.Path == Doc.Path and not Note.External) then
				Note.Title = TitleOf(Doc.Lines, Doc.Path)
			end
		end
	end
	return Ok
end

local function Open(Path)
	Save()
	Doc = { Path = Path, Lines = SplitLines(Config.ReadText(Path)), X = 1, Y = 1, Scroll = 0, GoalX = nil, Dirty = false }
	BlockOS.SetTitle(fs.getName(Path))
end

local function NewNote()
	Save()
	local Path = "/" .. fs.combine(Folder, "Note " .. os.date("%Y-%m-%d %H%M%S") .. ".txt")
	Config.WriteText(Path, "")
	Open(Path)
	LoadNotes()
end

--
-- Word wrap
--

-- Splits a line into visual rows, breaking after the last space that fits.
local function Segments(Text, Width)
	local Starts = { 1 }
	local Position = 1
	while (#Text - Position + 1 >= Width) do
		local Chunk = Text:sub(Position, Position + Width - 1)
		local Break = Chunk:match("^.*() ")
		if (Break and Break > 1) then
			Position = Position + Break
		else
			Position = Position + Width
		end
		table.insert(Starts, Position)
	end
	return Starts
end

local function Rewrap()
	Rows = {}
	local Width = math.max(4, Layout.EW)
	for Index, Line in ipairs(Doc.Lines) do
		local Starts = Segments(Line, Width)
		for Part, Start in ipairs(Starts) do
			local Stop = Starts[Part + 1] and (Starts[Part + 1] - 1) or (#Line + 1)
			table.insert(Rows, { Line = Index, Start = Start, Stop = Stop, Last = Starts[Part + 1] == nil })
		end
	end
end

local function CursorRow()
	for Index, Row in ipairs(Rows) do
		if (Row.Line == Doc.Y and Doc.X >= Row.Start and Doc.X <= Row.Stop) then
			return Index, Row
		end
	end
	return #Rows, Rows[#Rows]
end

local function EnsureVisible()
	local Index = CursorRow()
	if (Index <= Doc.Scroll) then
		Doc.Scroll = Index - 1
	elseif (Index > Doc.Scroll + Layout.EH) then
		Doc.Scroll = Index - Layout.EH
	end
	Doc.Scroll = math.max(0, math.min(Doc.Scroll, math.max(0, #Rows - 1)))
end

local function Changed()
	Doc.Dirty = true
	Doc.LastEdit = os.clock()
	Doc.GoalX = nil
	Rewrap()
	EnsureVisible()
end

--
-- Editing
--

local function Insert(Text)
	local Line = Doc.Lines[Doc.Y]
	Doc.Lines[Doc.Y] = Line:sub(1, Doc.X - 1) .. Text .. Line:sub(Doc.X)
	Doc.X = Doc.X + #Text
	Changed()
end

local function NewLine()
	local Line = Doc.Lines[Doc.Y]
	local Indent = Line:match("^([%-%*] )") or ""
	Doc.Lines[Doc.Y] = Line:sub(1, Doc.X - 1)
	table.insert(Doc.Lines, Doc.Y + 1, Indent .. Line:sub(Doc.X))
	Doc.Y = Doc.Y + 1
	Doc.X = #Indent + 1
	Changed()
end

local function Backspace()
	if (Doc.X > 1) then
		local Line = Doc.Lines[Doc.Y]
		Doc.Lines[Doc.Y] = Line:sub(1, Doc.X - 2) .. Line:sub(Doc.X)
		Doc.X = Doc.X - 1
	elseif (Doc.Y > 1) then
		local Previous = Doc.Lines[Doc.Y - 1]
		Doc.Lines[Doc.Y - 1] = Previous .. Doc.Lines[Doc.Y]
		table.remove(Doc.Lines, Doc.Y)
		Doc.Y = Doc.Y - 1
		Doc.X = #Previous + 1
	else
		return
	end
	Changed()
end

local function Delete()
	local Line = Doc.Lines[Doc.Y]
	if (Doc.X <= #Line) then
		Doc.Lines[Doc.Y] = Line:sub(1, Doc.X - 1) .. Line:sub(Doc.X + 1)
	elseif (Doc.Y < #Doc.Lines) then
		Doc.Lines[Doc.Y] = Line .. Doc.Lines[Doc.Y + 1]
		table.remove(Doc.Lines, Doc.Y + 1)
	else
		return
	end
	Changed()
end

local function MoveVertical(Step)
	local Index, Row = CursorRow()
	local Target = Rows[Index + Step]
	if (not Target) then
		Doc.X = (Step < 0) and 1 or (#Doc.Lines[Doc.Y] + 1)
		return
	end
	Doc.GoalX = Doc.GoalX or (Doc.X - Row.Start)
	Doc.Y = Target.Line
	Doc.X = math.min(Target.Start + Doc.GoalX, Target.Stop)
end

local function MoveHorizontal(Step)
	Doc.GoalX = nil
	if (Step < 0) then
		if (Doc.X > 1) then
			Doc.X = Doc.X - 1
		elseif (Doc.Y > 1) then
			Doc.Y = Doc.Y - 1
			Doc.X = #Doc.Lines[Doc.Y] + 1
		end
	elseif (Doc.X <= #Doc.Lines[Doc.Y]) then
		Doc.X = Doc.X + 1
	elseif (Doc.Y < #Doc.Lines) then
		Doc.Y = Doc.Y + 1
		Doc.X = 1
	end
end

local function HandleKey(Key)
	local Ctrl = Ui.Modifiers.Ctrl
	if (Ctrl and Key == keys.s) then
		Save()
	elseif (Ctrl and Key == keys.n) then
		NewNote()
		Build()
		return true
	elseif (Key == keys.enter or Key == keys.numPadEnter) then
		NewLine()
	elseif (Key == keys.backspace) then
		Backspace()
	elseif (Key == keys.delete) then
		Delete()
	elseif (Key == keys.tab) then
		Insert("  ")
	elseif (Key == keys.left or Key == keys.right) then
		MoveHorizontal(Key == keys.left and -1 or 1)
	elseif (Key == keys.up or Key == keys.down) then
		MoveVertical(Key == keys.up and -1 or 1)
	elseif (Key == keys.pageUp or Key == keys.pageDown) then
		for _ = 1, Layout.EH - 1 do
			MoveVertical(Key == keys.pageUp and -1 or 1)
		end
	elseif (Key == keys.home or Key == keys["end"]) then
		local _, Row = CursorRow()
		Doc.X = (Key == keys.home) and Row.Start or Row.Stop
		Doc.GoalX = nil
	else
		return false
	end
	EnsureVisible()
	return true
end

--
-- Layout
--

local function SelectNote(Path)
	Open(Path)
	Rewrap()
	Build()
end

local function DeleteCurrent()
	if (not Doc) then return end
	local Title = TitleOf(Doc.Lines, Doc.Path)
	if (not Ui.Confirm("Delete Note", "Delete \"" .. Gfx.Truncate(Title, 20) .. "\"?", "Delete")) then return end
	fs.delete(Doc.Path)
	Doc = nil
	LoadNotes()
	if (#Notes == 0) then
		NewNote()
	else
		Open(Notes[1].Path)
	end
	Rewrap()
	Build()
end

local Editor

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	Layout.SideW = (W >= 36) and 14 or 0
	Layout.EX = Layout.SideW + 2
	Layout.EY = 2
	Layout.EW = W - Layout.SideW - 2
	Layout.EH = H - 2
	Rewrap()
	EnsureVisible()

	Page:Add(Ui.Canvas.new({
		X = 1, Y = 1, W = W, H = 1,
		OnDraw = function(Self, T, Th)
			Gfx.Fill(T, Self.X, Self.Y, Self.W, 1, Th.Panel)
		end
	}))
	Page:Add(Ui.Button.new({ X = 1, Y = 1, Text = " + New ", Style = "plain", Bg = "Panel", OnClick = function()
		NewNote()
		Rewrap()
		Build()
	end }))
	Page:Add(Ui.Button.new({ X = 9, Y = 1, Text = " Delete ", Style = "plain", Bg = "Panel", OnClick = DeleteCurrent }))
	if (W >= 34) then
		Page:Add(Ui.Button.new({ X = 18, Y = 1, Text = " Print ", Style = "plain", Bg = "Panel", OnClick = function()
			Save()
			if (Doc.Path) then BlockOS.Launch("print", { Doc.Path }) end
		end }))
	end
	if (Layout.SideW == 0) then
		Page:Add(Ui.Button.new({ X = W - 7, Y = 1, W = 7, Text = "Notes \31", Style = "plain", Bg = "Panel", OnClick = function()
			local Names = {}
			for _, Note in ipairs(Notes) do table.insert(Names, Note.Title) end
			local Index = Ui.Choose("Notes", Names)
			if (Index) then SelectNote(Notes[Index].Path) end
		end }))
	end

	if (Layout.SideW > 0) then
		local Items = {}
		local Selected = 1
		for Index, Note in ipairs(Notes) do
			local Title = (Doc and Note.Path == Doc.Path) and TitleOf(Doc.Lines, Doc.Path) or Note.Title
			table.insert(Items, { Text = Title, Path = Note.Path })
			if (Doc and Note.Path == Doc.Path) then Selected = Index end
		end
		local List = Page:Add(Ui.List.new({ X = 1, Y = 2, W = Layout.SideW, H = H - 1, Bg = "Panel", SingleClick = true }))
		List:SetItems(Items)
		List.Selected = Selected
		List.OnActivate = function(_, _, Item)
			if (Item and (not Doc or Item.Path ~= Doc.Path)) then
				SelectNote(Item.Path)
			else
				Page:SetFocus(Editor)
			end
		end
	end

	Editor = Page:Add(Ui.Canvas.new({
		X = Layout.EX, Y = Layout.EY, W = Layout.EW, H = Layout.EH, Focusable = true, KeepFocus = true,
		OnDraw = function(Self, T, Th)
			for Offset = 1, Self.H do
				local Row = Rows[Doc.Scroll + Offset]
				local Text = ""
				local Fg = Th.Text
				if (Row) then
					Text = Doc.Lines[Row.Line]:sub(Row.Start, Row.Last and #Doc.Lines[Row.Line] or Row.Stop)
					if (Row.Line == 1) then Fg = Th.Accent end
				end
				Gfx.Write(T, Self.X, Self.Y + Offset - 1, Gfx.Pad(Text, Self.W), Fg, Th.WindowBg)
			end
		end,
		OnCursor = function(Self, Th)
			local Index, Row = CursorRow()
			local Y = Index - Doc.Scroll
			if (Y < 1 or Y > Self.H) then return nil end
			return Self.X + Doc.X - Row.Start, Self.Y + Y - 1, Th.Text
		end,
		OnEvent = function(Self, Name, A, B, C)
			if (Name == "char") then
				Insert(A)
				return true
			elseif (Name == "paste") then
				Insert((A:gsub("[\r\n]", " ")))
				return true
			elseif (Name == "key") then
				return HandleKey(A)
			elseif (Name == "mouse_click" or Name == "mouse_drag") then
				local Row = Rows[Doc.Scroll + C - Self.Y + 1] or Rows[#Rows]
				Doc.Y = Row.Line
				Doc.X = math.max(Row.Start, math.min(Row.Start + B - Self.X, Row.Stop))
				Doc.GoalX = nil
				return true
			elseif (Name == "mouse_scroll") then
				Doc.Scroll = math.max(0, math.min(Doc.Scroll + A * 2, math.max(0, #Rows - Self.H)))
				return true
			end
			return false
		end
	}))

	Page:Add(Ui.Label.new({
		X = Layout.EX, Y = H, W = Layout.EW, Fg = "SubText",
		Text = function()
			local Words = WordCount()
			return (Doc.Dirty and "Edited" or "Saved") .. " \7 " .. Words .. (Words == 1 and " word" or " words")
		end
	}))
	Page:SetFocus(Editor)
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name, A)
	if (Name == "blockos_close") then
		Save()
		self:Stop()
		return true
	elseif (Name == "blockos_open" and A and fs.exists(A)) then
		Open(A)
		LoadNotes()
		Build()
		return true
	end
	return false
end

function Page:OnTerminate()
	Save()
	self:Stop()
end

-- Autosave a moment after typing stops.
Page:SetInterval(1, function()
	if (Doc and Doc.Dirty and os.clock() - (Doc.LastEdit or 0) >= SaveDelay) then
		Save()
		return true
	end
	return false
end)

BlockOS.SetCloseHandler(true)
local Target = Args[1] and (shell and shell.resolve(Args[1]) or Args[1])
if (Target and not Target:find("^/")) then Target = "/" .. Target end
if (Target and fs.exists(Target) and not fs.isDir(Target)) then
	Open(Target)
	LoadNotes()
else
	LoadNotes()
	if (#Notes == 0) then
		NewNote()
	else
		Open(Notes[1].Path)
	end
end
Page:Run()
Save()
]]
Files["blockos/apps/print/app.cfg"] = [[
{ Name = "Print", Description = "Print text files on an attached printer.", Width = 44, Height = 16, Single = true, Icon = { Lines = { " \131 ", "\143\143\143" }, Fg = "gray", Bg = "white" } }
]]
Files["blockos/apps/print/main.lua"] = [[
-- Print: lays text files out on printed pages and sends them to an attached printer.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")

local Args = { ... }

-- Every CC printer page is 25 characters by 21 lines.
local PageW, PageH = 25, 21

local Page = Ui.Page.new()
local Doc = { Path = nil, Pages = {}, Title = "" }
local Copies = 1
local Shown = 1
local Scroll = 0
local PrinterName = nil
local Status = nil
local Busy = false
local TitleField
local Build

local function Printers()
	local List = {}
	for _, Name in ipairs(peripheral.getNames()) do
		if (peripheral.getType(Name) == "printer") then
			table.insert(List, { Name = Name, Device = peripheral.wrap(Name) })
		end
	end
	return List
end

local function CurrentPrinter()
	local List = Printers()
	for _, Printer in ipairs(List) do
		if (Printer.Name == PrinterName) then return Printer end
	end
	if (List[1]) then PrinterName = List[1].Name end
	return List[1]
end

-- Wraps one line to the page width, breaking at spaces where possible and keeping indentation.
local function WrapLine(Line, Width)
	local Rows = {}
	Line = Line:gsub("\t", "  ")
	while (#Line > Width) do
		local Space = Line:sub(1, Width + 1):match(".*() ")
		if (Space and Space > 1) then
			table.insert(Rows, Line:sub(1, Space - 1))
			Line = Line:sub(Space + 1)
		else
			table.insert(Rows, Line:sub(1, Width))
			Line = Line:sub(Width + 1)
		end
	end
	table.insert(Rows, Line)
	return Rows
end

local function Paginate(Text)
	local Pages = {}
	local Current = {}
	Text = Text:gsub("\r\n?", "\n")
	for Line in (Text .. "\n"):gmatch("(.-)\n") do
		for _, Row in ipairs(WrapLine(Line, PageW)) do
			if (#Current == PageH) then
				table.insert(Pages, Current)
				Current = {}
			end
			table.insert(Current, Row)
		end
	end
	-- Drop trailing blank lines so a final newline does not cost a sheet of paper.
	while (#Current > 0 and Current[#Current]:match("^%s*$")) do
		table.remove(Current)
	end
	if (#Current > 0 or #Pages == 0) then table.insert(Pages, Current) end
	return Pages
end

local function Load(Path)
	local Handle = Path and fs.exists(Path) and not fs.isDir(Path) and fs.open(Path, "r")
	if (not Handle) then
		Status = Path and ("Cannot open " .. fs.getName(Path)) or nil
		return false
	end
	local Text = Handle.readAll() or ""
	Handle.close()
	Doc.Path = Path
	Doc.Pages = Paginate(Text)
	Doc.Title = (fs.getName(Path):gsub("%.[^%.]+$", ""))
	Shown, Scroll = 1, 0
	Status = nil
	BlockOS.SetTitle("Print \7 " .. fs.getName(Path))
	return true
end

-- Two short lines: ink and paper levels, or why there are none.
local function PrinterStatus(Printer)
	if (not Printer) then return "No printer", "attached" end
	local Ok, Ink = pcall(Printer.Device.getInkLevel)
	local _, Paper = pcall(Printer.Device.getPaperLevel)
	if (not Ok) then return "Not responding", "" end
	return "Ink " .. tostring(Ink), "Paper " .. tostring(Paper)
end

local function PrintDocument()
	if (Busy or #Doc.Pages == 0) then return end
	local Printer = CurrentPrinter()
	if (not Printer) then
		Status = "Attach a printer next to the computer or over a wired modem."
		return
	end
	local Device = Printer.Device
	local Title = (#TitleField.Value > 0) and TitleField.Value or Doc.Title
	local Total = #Doc.Pages * Copies
	local Done = 0
	Busy = true
	for _ = 1, Copies do
		for Index, Lines in ipairs(Doc.Pages) do
			if (not Device.newPage()) then
				if (Device.getPaperLevel() == 0) then
					Status = "Out of paper. Add paper to the printer and try again."
				elseif (Device.getInkLevel() == 0) then
					Status = "Out of ink. Add a dye to the printer and try again."
				else
					Status = "The output tray is full. Take the printed pages out."
				end
				Busy = false
				return
			end
			Device.setPageTitle((#Doc.Pages > 1) and (Title .. " " .. Index .. "/" .. #Doc.Pages) or Title)
			for Row, Line in ipairs(Lines) do
				Device.setCursorPos(1, Row)
				Device.write(Line)
			end
			if (not Device.endPage()) then
				Status = "The output tray is full. Take the printed pages out."
				Busy = false
				return
			end
			Done = Done + 1
			Status = "Printing page " .. Done .. " of " .. Total .. "..."
			Page:Draw()
		end
	end
	Busy = false
	Status = "Printed " .. Total .. ((Total == 1) and " page." or " pages.")
	BlockOS.Notify("Print", Title .. " \7 " .. Total .. ((Total == 1) and " page" or " pages"), { Sound = false })
end

local function ChooseFile()
	local Path = Ui.PickFile({ Title = "Print", Dir = Doc.Path and fs.getDir(Doc.Path) or "/home" })
	if (Path and Load(Path)) then
		Build()
	elseif (Path) then
		Build()
	end
end

local function ChoosePrinter(X, Y)
	local List = Printers()
	if (#List == 0) then return end
	local Options = {}
	for _, Printer in ipairs(List) do
		table.insert(Options, { Text = Printer.Name })
	end
	local Index = Ui.ContextMenu(X, Y, Options)
	if (Index) then PrinterName = List[Index].Name end
end

local function DrawPreview(Self, T, Th)
	Gfx.Fill(T, Self.X, Self.Y, Self.W, Self.H, Th.Panel)
	local Lines = Doc.Pages[Shown]
	if (not Lines) then
		local Message = Gfx.Wrap("Choose a text file to print, or right-click one in Finder and pick Print.", Self.W - 4)
		for Row, Line in ipairs(Message) do
			Gfx.Write(T, Self.X + 2, Self.Y + Row, Line, Th.SubText, Th.Panel)
		end
		return
	end
	local PaperX = Self.X + math.max(0, math.floor((Self.W - PageW) / 2))
	for Row = 1, math.min(Self.H, PageH - Scroll) do
		local Line = Lines[Row + Scroll] or ""
		Gfx.Write(T, PaperX, Self.Y + Row - 1, Gfx.Pad(Line, PageW), colors.black, colors.white)
	end
end

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	local SideW = 16
	local PreviewW = math.max(PageW + 2, W - SideW - 1)
	local SideX = PreviewW + 2
	local Narrow = SideX + SideW - 1 > W

	Page:Add(Ui.Panel.new({ X = 1, Y = 1, W = W, H = 1, Bg = "Panel" }))
	Page:Add(Ui.Label.new({ X = 2, Y = 1, W = W - 12, Bg = "Panel", Text = function()
		return Doc.Path and fs.getName(Doc.Path) or "No document"
	end }))
	Page:Add(Ui.Button.new({ X = W - 8, Y = 1, W = 9, Text = "Open...", Bg = "Panel", OnClick = ChooseFile }))

	Page:Add(Ui.Canvas.new({
		X = 1, Y = 2, W = Narrow and W or PreviewW, H = H - 1,
		OnDraw = DrawPreview,
		OnEvent = function(_, Name, A)
			if (Name == "mouse_scroll") then
				Scroll = math.max(0, math.min(PageH - (H - 1), Scroll + A * 2))
				return true
			end
			return false
		end
	}))
	if (Narrow) then
		Page:Add(Ui.Button.new({ X = W - 8, Y = H, W = 9, Text = "Print", Style = "primary", OnClick = PrintDocument }))
		return
	end

	Page:Add(Ui.Label.new({ X = SideX, Y = 2, Text = "Printer", Fg = "SubText" }))
	local PickPrinter
	PickPrinter = Page:Add(Ui.Button.new({ X = SideX, Y = 3, W = SideW, Text = function()
		local Printer = CurrentPrinter()
		return Gfx.Truncate(Printer and Printer.Name or "None", SideW - 3) .. " \31"
	end, OnClick = function() ChoosePrinter(PickPrinter.X, PickPrinter.Y + 1) end }))
	Page:Add(Ui.Label.new({ X = SideX, Y = 4, W = SideW, Fg = "SubText", Text = function()
		return (PrinterStatus(CurrentPrinter()))
	end }))
	Page:Add(Ui.Label.new({ X = SideX, Y = 5, W = SideW, Fg = "SubText", Text = function()
		return select(2, PrinterStatus(CurrentPrinter()))
	end }))

	Page:Add(Ui.Label.new({ X = SideX, Y = 6, Text = "Title", Fg = "SubText" }))
	TitleField = Page:Add(Ui.Input.new({ X = SideX, Y = 7, W = SideW, Value = Doc.Title, Placeholder = "Page title", MaxLength = 30 }))

	Page:Add(Ui.Label.new({ X = SideX, Y = 9, Text = "Copies", Fg = "SubText" }))
	Page:Add(Ui.Button.new({ X = SideX + 8, Y = 9, W = 3, Text = "-", OnClick = function() Copies = math.max(1, Copies - 1) end }))
	Page:Add(Ui.Label.new({ X = SideX + 11, Y = 9, W = 3, Align = "center", Text = function() return tostring(Copies) end }))
	Page:Add(Ui.Button.new({ X = SideX + 14, Y = 9, W = 2, Text = "+", OnClick = function() Copies = math.min(64, Copies + 1) end }))

	Page:Add(Ui.Button.new({ X = SideX, Y = 11, W = 3, Text = "\17", OnClick = function()
		Shown = math.max(1, Shown - 1)
		Scroll = 0
	end }))
	Page:Add(Ui.Label.new({ X = SideX + 3, Y = 11, W = SideW - 6, Align = "center", Text = function()
		return "Page " .. math.min(Shown, #Doc.Pages) .. "/" .. #Doc.Pages
	end }))
	Page:Add(Ui.Button.new({ X = SideX + SideW - 3, Y = 11, W = 3, Text = "\16", OnClick = function()
		Shown = math.min(#Doc.Pages, Shown + 1)
		Scroll = 0
	end }))

	Page:Add(Ui.Button.new({ X = SideX, Y = 13, W = SideW, Text = "Print", Style = "primary", OnClick = PrintDocument }))
	Page:Add(Ui.Label.new({ X = SideX, Y = 14, W = SideW, H = math.max(1, H - 13), Fg = "SubText", Text = function()
		return Status or ""
	end }))
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name, A)
	if (Name == "peripheral" or Name == "peripheral_detach") then
		return true
	elseif (Name == "blockos_open" and A) then
		if (Load(A)) then Build() end
		return true
	end
	return false
end

Load(Args[1])
Page:Run()
]]
Files["blockos/apps/recorder/app.cfg"] = [[
{ Name = "Recorder", Description = "Record the screen and play recordings back.", Width = 40, Height = 13, Single = true, Icon = { Lines = { " \7 ", "REC" }, Fg = "red", Bg = "black" } }
]]
Files["blockos/apps/recorder/main.lua"] = [=[
-- Recorder: captures the BlockOS screen into .rec files, plays them back,
-- and can export a recording as a standalone player program.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Config = BlockOS.Require("config")

local Args = { ... }

local Folder = "/home/Recordings"
local MaxFrames = 2000

local Page = Ui.Page.new()
local Recording = nil
local Options = { Hide = true, Countdown = true, Fps = 8 }
local Build

local function Serialise(Value)
	local Ok, Text = pcall(textutils.serialise, Value, { compact = true })
	if (Ok) then return Text end
	return textutils.serialise(Value)
end

local function ListRecordings()
	if (not fs.exists(Folder)) then fs.makeDir(Folder) end
	local Items = {}
	for _, Name in ipairs(fs.list(Folder)) do
		if (Name:match("%.rec$")) then
			local Path = fs.combine(Folder, Name)
			table.insert(Items, { Text = Name:gsub("%.rec$", ""), Right = Gfx.FormatSize(fs.getSize(Path)), Icon = "\7", IconFg = colors.red, Path = "/" .. Path })
		end
	end
	table.sort(Items, function(A, B) return A.Text > B.Text end)
	return Items
end

local function Capture()
	local Frame = BlockOS.Capture()
	local Now = os.epoch("utc")
	local Changed = {}
	local Any = false
	for Y, Line in ipairs(Frame.Lines) do
		local Previous = Recording.Last[Y]
		if (not Previous or Previous[1] ~= Line[1] or Previous[2] ~= Line[2] or Previous[3] ~= Line[3]) then
			Changed[Y] = Line
			Recording.Last[Y] = Line
			Any = true
		end
	end
	if (Any) then
		table.insert(Recording.Frames, { T = Now - Recording.Started, Lines = Changed })
	end
	Recording.W, Recording.H = Frame.W, Frame.H
end

local function StopRecording()
	if (not Recording) then return end
	Page:ClearInterval(Recording.Interval)
	BlockOS.SetRecording(false)
	local Data = {
		Version = 1,
		W = Recording.W,
		H = Recording.H,
		Duration = os.epoch("utc") - Recording.Started,
		Frames = Recording.Frames
	}
	Recording = nil
	if (#Data.Frames == 0) then return end
	local Path = fs.combine(Folder, "Recording " .. os.date("%Y-%m-%d %H%M%S") .. ".rec")
	Config.WriteText(Path, Serialise(Data))
	BlockOS.Notify("Recorder", "Saved " .. fs.getName(Path), { AppID = "recorder", Sound = false })
	Build()
end

local function StartRecording()
	if (Recording) then return end
	if (Options.Countdown) then
		for Count = 3, 1, -1 do
			BlockOS.Notify("Recorder", "Recording starts in " .. Count .. "...", { Sound = false, Duration = 1 })
			sleep(1)
		end
	end
	Recording = { Frames = {}, Last = {}, Started = os.epoch("utc") }
	BlockOS.SetRecording(true)
	if (Options.Hide) then BlockOS.Minimize() end
	Capture()
	Recording.Interval = Page:SetInterval(1 / Options.Fps, function()
		if (not Recording) then return false end
		Capture()
		if (#Recording.Frames >= MaxFrames) then StopRecording() end
		return true
	end)
	Build()
end

local function LoadRecording(Path)
	local Data = textutils.unserialise(Config.ReadText(Path) or "")
	if (type(Data) ~= "table" or type(Data.Frames) ~= "table") then return nil end
	return Data
end

-- Plays a recording full screen; any click or key other than space stops it.
local function Play(Path)
	local Data = LoadRecording(Path)
	if (not Data) then
		Ui.Alert("Recorder", "This file is not a valid recording.")
		return
	end
	BlockOS.SetFullscreen(true)
	sleep(0)
	local T = term.current()
	local W, H = T.getSize()
	local Screen = window.create(T, 1, 1, W, H, true)
	Screen.setBackgroundColor(colors.black)
	Screen.clear()
	local Paused = false
	local Index = 1
	local Clock = 0
	local Last = os.epoch("utc")
	local Timer = os.startTimer(0)
	while (Index <= #Data.Frames) do
		local Event = table.pack(os.pullEventRaw())
		local Name = Event[1]
		if (Name == "terminate" or Name == "mouse_click" or (Name == "key" and Event[2] ~= keys.space)) then
			break
		elseif (Name == "key" and Event[2] == keys.space) then
			Paused = not Paused
			Last = os.epoch("utc")
		elseif (Name == "timer" and Event[2] == Timer) then
			local Now = os.epoch("utc")
			if (not Paused) then Clock = Clock + (Now - Last) end
			Last = Now
			while (Index <= #Data.Frames and Data.Frames[Index].T <= Clock) do
				for Y, Line in pairs(Data.Frames[Index].Lines) do
					if (Y <= H) then
						Screen.setCursorPos(1, Y)
						Screen.blit(Line[1]:sub(1, W), Line[2]:sub(1, W), Line[3]:sub(1, W))
					end
				end
				Index = Index + 1
			end
			Timer = os.startTimer(.05)
		end
	end
	sleep(.5)
	Screen.setVisible(false)
	BlockOS.SetFullscreen(false)
	sleep(0)
	Page:Resize()
	Page:Draw()
end

local PlayerTemplate = [[
-- BlockOS recording player (exported by Recorder)
local Data = textutils.unserialise(%q)
local W, H = term.getSize()
term.setBackgroundColor(colors.black)
term.clear()
local Start = os.epoch("utc")
for _, Frame in ipairs(Data.Frames) do
	local Wait = Frame.T - (os.epoch("utc") - Start)
	if (Wait > 0) then sleep(Wait / 1000) end
	for Y, Line in pairs(Frame.Lines) do
		if (Y <= H) then
			term.setCursorPos(1, Y)
			term.blit(Line[1]:sub(1, W), Line[2]:sub(1, W), Line[3]:sub(1, W))
		end
	end
end
term.setCursorPos(1, H)
]]

local function Export(Item)
	local Data = Config.ReadText(Item.Path)
	if (not Data) then return end
	local Target = Item.Path:gsub("%.rec$", "") .. " player.lua"
	Config.WriteText(Target, string.format(PlayerTemplate, Data))
	Ui.Alert("Export", "Saved a standalone player to " .. Target .. ". Run it on any advanced computer.")
	Build()
end

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	Page:Add(Ui.Canvas.new({
		X = 1, Y = 1, W = W, H = 4,
		OnDraw = function(Self, T, Th)
			Gfx.Fill(T, Self.X, Self.Y, Self.W, Self.H, Th.Panel)
			local Color = Recording and colors.red or colors.gray
			Gfx.Fill(T, Self.X + 2, Self.Y + 1, 4, 2, Recording and colors.red or Th.WindowBg)
			Gfx.Write(T, Self.X + 3, Self.Y + 1, "\7\7", Recording and colors.white or colors.red, Recording and colors.red or Th.WindowBg)
			if (Recording) then
				local Seconds = math.floor((os.epoch("utc") - Recording.Started) / 1000)
				Gfx.Write(T, Self.X + 8, Self.Y + 1, string.format("Recording %d:%02d", math.floor(Seconds / 60), Seconds % 60), Color, Th.Panel)
				Gfx.Write(T, Self.X + 8, Self.Y + 2, #Recording.Frames .. " frames \7 click to stop", Th.SubText, Th.Panel)
			else
				Gfx.Write(T, Self.X + 8, Self.Y + 1, "Record Screen", Th.PanelFg, Th.Panel)
				Gfx.Write(T, Self.X + 8, Self.Y + 2, Gfx.Truncate("Stop from the REC item in the menu bar", Self.W - 9), Th.SubText, Th.Panel)
			end
		end,
		OnEvent = function(_, Name)
			if (Name ~= "mouse_click") then return false end
			if (Recording) then StopRecording() else StartRecording() end
			return true
		end
	}))
	Page:Add(Ui.Checkbox.new({ X = 2, Y = 6, Text = "Hide window", Value = Options.Hide, OnChange = function(_, Value) Options.Hide = Value end }))
	Page:Add(Ui.Checkbox.new({ X = 18, Y = 6, Text = "Countdown", Value = Options.Countdown, OnChange = function(_, Value) Options.Countdown = Value end }))
	local List = Page:Add(Ui.List.new({ X = 1, Y = 8, W = W, H = H - 8 }))
	List:SetItems(ListRecordings())
	List.OnActivate = function(_, _, Item) Play(Item.Path) end
	List.OnContext = function(_, _, Item, X, Y)
		if (not Item) then return end
		local Choices = { "Play", "Export Player", "Rename", "Show in Finder", "-", "Delete" }
		local Choice = Choices[Ui.ContextMenu(X, Y, Choices) or 0]
		if (Choice == "Play") then
			Play(Item.Path)
		elseif (Choice == "Export Player") then
			Export(Item)
		elseif (Choice == "Rename") then
			local Name = Ui.Prompt("Rename", "Name:", Item.Text)
			if (Name and #Name > 0) then
				local Target = fs.combine(Folder, Name .. ".rec")
				if (not fs.exists(Target)) then fs.move(Item.Path, Target) end
				Build()
			end
		elseif (Choice == "Show in Finder") then
			BlockOS.Launch("finder", { Folder })
		elseif (Choice == "Delete") then
			if (Ui.Confirm("Delete", "Delete \"" .. Item.Text .. "\"?", "Delete")) then
				fs.delete(Item.Path)
				Build()
			end
		end
	end
	if (#List.Items == 0) then
		Page:Add(Ui.Label.new({ X = 2, Y = 9, W = W - 2, Text = "No recordings yet.", Fg = "SubText" }))
	end
	Page:Add(Ui.Label.new({ X = 1, Y = H, W = W, Bg = "Panel", Fg = "SubText", Text = " Double-click to play \7 space pauses" }))
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name, A)
	if (Name == "blockos_recorder_stop") then
		StopRecording()
		return true
	elseif (Name == "blockos_open" and A) then
		Play(A)
		return true
	end
	return false
end

function Page:OnTerminate()
	StopRecording()
	self:Stop()
end

Page:SetInterval(1, function() return Recording ~= nil end)

if (Args[1] and fs.exists(Args[1])) then
	Play(Args[1])
end
Page:Run()
StopRecording()
]=]
Files["blockos/apps/reminders/app.cfg"] = [[
{ Name = "Reminders", Description = "Lists and reminders with due-time notifications.", Width = 44, Height = 14, Single = true, Icon = { Lines = { "\7\140\140", "\7\140\140" }, Fg = "orange", Bg = "white" } }
]]
Files["blockos/apps/reminders/main.lua"] = [[
-- Reminders: smart lists, custom lists, due times and priorities.
-- Quick entry: "Buy bread !! @ tomorrow 9:00" sets priority 2 and a due time.

local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Schedule = BlockOS.Require("schedule")

local Page = Ui.Page.new()
local Data = Schedule.Load()
local Current = { Kind = "smart", ID = "today" }
local Build

local Smart = {
	{ ID = "today", Name = "Today", Icon = "\15", Color = colors.blue },
	{ ID = "scheduled", Name = "Scheduled", Icon = "\4", Color = colors.red },
	{ ID = "all", Name = "All", Icon = "\7", Color = colors.gray },
	{ ID = "done", Name = "Completed", Icon = "x", Color = colors.green }
}

local function EndOfToday()
	local Now = Schedule.Now()
	local Today = os.date("!*t", Now)
	return Now - (Today.hour * 3600 + Today.min * 60 + Today.sec) + 86399
end

local function Matches(Reminder)
	if (Current.Kind == "list") then
		return Reminder.List == Current.ID and not Reminder.Done
	end
	if (Current.ID == "done") then return Reminder.Done end
	if (Reminder.Done) then return false end
	if (Current.ID == "today") then
		return Reminder.Due ~= nil and Reminder.Due <= EndOfToday()
	elseif (Current.ID == "scheduled") then
		return Reminder.Due ~= nil
	end
	return true
end

local function Visible()
	local Result = {}
	for _, Reminder in ipairs(Data.Reminders) do
		if (Matches(Reminder)) then
			table.insert(Result, Reminder)
		end
	end
	table.sort(Result, function(A, B)
		if ((A.Due ~= nil) ~= (B.Due ~= nil)) then return A.Due ~= nil end
		if (A.Due and B.Due and A.Due ~= B.Due) then return A.Due < B.Due end
		if ((A.Priority or 0) ~= (B.Priority or 0)) then return (A.Priority or 0) > (B.Priority or 0) end
		return A.ID < B.ID
	end)
	return Result
end

local function CountFor(Kind, ID)
	local Saved = Current
	Current = { Kind = Kind, ID = ID }
	local Count = #Visible()
	Current = Saved
	return Count
end

local function CurrentName()
	if (Current.Kind == "list") then return Current.ID end
	for _, Entry in ipairs(Smart) do
		if (Entry.ID == Current.ID) then return Entry.Name end
	end
	return ""
end

local function QuickAdd(Text)
	Text = Text:gsub("^%s+", ""):gsub("%s+$", "")
	if (#Text == 0) then return end
	local Due
	local Title, DueText = Text:match("^(.-)%s*@%s*(.+)$")
	if (Title) then
		Due = Schedule.ParseDue(DueText)
		if (not Due) then
			Ui.Alert("Reminders", "Could not understand \"" .. DueText .. "\". Try \"in 10m\", \"14:30\", \"tomorrow 9:00\" or \"2026-11-02 08:00\".")
			return
		end
		Text = Title
	end
	local Bangs = Text:match("(!+)%s*$")
	local Priority = 0
	if (Bangs) then
		Priority = math.min(3, #Bangs)
		Text = Text:gsub("%s*!+%s*$", "")
	end
	if (not Due and Current.Kind == "smart" and Current.ID == "today") then
		Due = EndOfToday() - 59
	end
	Schedule.AddReminder({
		Title = Text,
		Due = Due,
		Priority = Priority,
		List = (Current.Kind == "list") and Current.ID or (Data.Lists[1] or "Personal")
	})
end

local function EditMenu(Reminder, X, Y)
	local Options = { Reminder.Done and "Mark Incomplete" or "Mark Complete", "Rename...", "Set Due...", "Clear Due", "Priority...", "Move to List...", "Notes...", "-", "Delete" }
	local Choice = Options[Ui.ContextMenu(X, Y, Options) or 0]
	if (Choice == "Mark Complete" or Choice == "Mark Incomplete") then
		Reminder.Done = not Reminder.Done
	elseif (Choice == "Rename...") then
		Reminder.Title = Ui.Prompt("Rename", "Title:", Reminder.Title) or Reminder.Title
	elseif (Choice == "Set Due...") then
		local Text = Ui.Prompt("Due", "When? (in 10m, 14:30, tomorrow 9:00)", "")
		local Due = Text and Schedule.ParseDue(Text)
		if (Due) then
			Reminder.Due = Due
			Reminder.Notified = false
		elseif (Text) then
			Ui.Alert("Due", "That time was not understood.")
		end
	elseif (Choice == "Clear Due") then
		Reminder.Due = nil
	elseif (Choice == "Priority...") then
		local Index = Ui.Choose("Priority", { "None", "Low (!)", "Medium (!!)", "High (!!!)" }, (Reminder.Priority or 0) + 1)
		if (Index) then Reminder.Priority = Index - 1 end
	elseif (Choice == "Move to List...") then
		local Index = Ui.Choose("Move to", Data.Lists)
		if (Index) then Reminder.List = Data.Lists[Index] end
	elseif (Choice == "Notes...") then
		Reminder.Notes = Ui.Prompt("Notes", Reminder.Title, Reminder.Notes or "") or Reminder.Notes
	elseif (Choice == "Delete") then
		Schedule.RemoveReminder(Reminder.ID)
		Build()
		return
	end
	Schedule.Save()
	Build()
end

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	local SideW = (W >= 36) and 14 or 0
	local Sidebar = Page:Add(Ui.List.new({ X = 1, Y = 1, W = SideW, H = H - 1, Bg = "Panel", SingleClick = true, Focusable = false, Visible = SideW > 0 }))
	local Entries = {}
	local Selected = 0
	for _, Entry in ipairs(Smart) do
		table.insert(Entries, { Text = Entry.Name, Icon = Entry.Icon, IconFg = Entry.Color, Right = tostring(CountFor("smart", Entry.ID)), Kind = "smart", ID = Entry.ID })
		if (Current.Kind == "smart" and Current.ID == Entry.ID) then Selected = #Entries end
	end
	table.insert(Entries, { Text = "My Lists", Header = true })
	for _, Name in ipairs(Data.Lists) do
		table.insert(Entries, { Text = Name, Icon = "\7", IconFg = colors.orange, Right = tostring(CountFor("list", Name)), Kind = "list", ID = Name })
		if (Current.Kind == "list" and Current.ID == Name) then Selected = #Entries end
	end
	Sidebar:SetItems(Entries)
	Sidebar.Selected = Selected
	Sidebar.OnActivate = function(_, _, Item)
		if (Item.Header) then return end
		Current = { Kind = Item.Kind, ID = Item.ID }
		Build()
	end
	Sidebar.OnContext = function(_, _, Item, X, Y)
		local Options = { "New List..." }
		if (Item and Item.Kind == "list") then
			table.insert(Options, "Rename List...")
			table.insert(Options, "Delete List")
		end
		local Choice = Options[Ui.ContextMenu(X, Y, Options) or 0]
		if (Choice == "New List...") then
			local Name = Ui.Prompt("New List", "Name:", "")
			if (Name and #Name > 0) then
				table.insert(Data.Lists, Name)
				Schedule.Save()
				Current = { Kind = "list", ID = Name }
			end
		elseif (Choice == "Rename List...") then
			local Name = Ui.Prompt("Rename List", "Name:", Item.ID)
			if (Name and #Name > 0) then
				for Index, Existing in ipairs(Data.Lists) do
					if (Existing == Item.ID) then Data.Lists[Index] = Name end
				end
				for _, Reminder in ipairs(Data.Reminders) do
					if (Reminder.List == Item.ID) then Reminder.List = Name end
				end
				Current = { Kind = "list", ID = Name }
				Schedule.Save()
			end
		elseif (Choice == "Delete List") then
			if (Ui.Confirm("Delete List", "Delete \"" .. Item.ID .. "\" and its reminders?", "Delete")) then
				for Index = #Data.Lists, 1, -1 do
					if (Data.Lists[Index] == Item.ID) then table.remove(Data.Lists, Index) end
				end
				for Index = #Data.Reminders, 1, -1 do
					if (Data.Reminders[Index].List == Item.ID) then table.remove(Data.Reminders, Index) end
				end
				Current = { Kind = "smart", ID = "all" }
				Schedule.Save()
			end
		end
		Build()
	end
	Page:Add(Ui.Button.new({ X = 1, Y = H, W = math.max(SideW, 1), Text = "+ List", Bg = "Panel", Visible = SideW > 0, OnClick = function()
		local Name = Ui.Prompt("New List", "Name:", "")
		if (Name and #Name > 0) then
			table.insert(Data.Lists, Name)
			Schedule.Save()
			Current = { Kind = "list", ID = Name }
			Build()
		end
	end }))

	local MainX = SideW + 2
	local MainW = W - SideW - 2
	local Items = Visible()
	Page:Add(Ui.Label.new({ X = MainX, Y = 1, W = MainW - 4, Text = CurrentName(), Fg = "Accent" }))
	Page:Add(Ui.Label.new({ X = MainX + MainW - 4, Y = 1, W = 4, Text = tostring(#Items), Fg = "SubText", Align = "right" }))
	local List = Page:Add(Ui.List.new({ X = MainX, Y = 3, W = MainW, H = H - 4 }))
	local Rows = {}
	for _, Reminder in ipairs(Items) do
		table.insert(Rows, { Reminder = Reminder })
	end
	List:SetItems(Rows)
	List.RenderItem = function(_, T, Th, Item, X, Y, Width, IsSelected, RowBg, RowFg)
		local Reminder = Item.Reminder
		local Box = Reminder.Done and "\7" or "o"
		Gfx.Write(T, X, Y, Box, Reminder.Done and Th.Accent or Th.SubText, RowBg)
		local Bang = string.rep("!", Reminder.Priority or 0)
		local Due = Reminder.Due and Schedule.FormatDue(Reminder.Due) or ""
		local Overdue = Reminder.Due and not Reminder.Done and Reminder.Due < Schedule.Now()
		local TitleW = Width - 2 - #Due - 1
		local Title = (#Bang > 0 and (Bang .. " ") or "") .. Reminder.Title .. (Reminder.Notes and " \26" or "")
		Gfx.Write(T, X + 2, Y, Gfx.Truncate(Title, TitleW), IsSelected and RowFg or (Reminder.Done and Th.SubText or Th.Text), RowBg)
		if (#Due > 0) then
			Gfx.Write(T, X + Width - #Due, Y, Due, IsSelected and RowFg or (Overdue and colors.red or Th.SubText), RowBg)
		end
	end
	List.OnActivate = function(_, _, Item)
		Item.Reminder.Done = not Item.Reminder.Done
		Schedule.Save()
		Build()
	end
	List.OnContext = function(_, _, Item, X, Y)
		if (Item) then EditMenu(Item.Reminder, X, Y) end
	end
	if (#Rows == 0) then
		Page:Add(Ui.Label.new({ X = MainX, Y = 4, W = MainW, H = 2, Text = "No reminders. Type below to add one.", Fg = "SubText" }))
	end
	local Entry = Page:Add(Ui.Input.new({ X = MainX, Y = H, W = MainW, Placeholder = "+ New reminder  (!! priority, @ in 10m)" }))
	Entry.OnSubmit = function(Self, Value)
		QuickAdd(Value)
		Self:SetValue("")
		Build()
	end
	Page:SetFocus(Entry)
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

function Page:OnEvent(Name)
	if (Name == "blockos_schedule") then
		if (not (self.Focus and self.Focus.Value and #self.Focus.Value > 0)) then
			Build()
		end
		return true
	end
	return false
end

Page:Run()
]]
